		function Andrew_Ryan_guidestar_stats__yahoo(rs, out_div) {
			// process result using AMT___xhr_PROXY_REDACTED_!
			// -> returns array of arrays
			// -> rs [ [m[1],m[2]], [m[1], m[2]], [ ... ] ]
			
			out_div.innerHTML = '';
			
			//console.log(rs);
			
			var eid, i;
			
			for (i in rs) {
				
				// eid !
				// https://www.guidestar.org/organizations/13-4199270/apne-aap-international.aspx
				// 13-4199270
				eid = /^https?:\/\/www\.guidestar\.org\/organizations\/([\d\-]+)\//.exec(rs[i][0])[1];
				
				// output
				
				var el_div = document.createElement('div');
				el_div.setAttribute('style','cursor:pointer;border-bottom:1px solid teal;');//margin-bottom:4px;
				el_div.setAttribute('class','class__highlightURL__'+rs[i][0]);
				el_div.isClicked = false;
				el_div.gs_link = rs[i][0];
				el_div.gs_eid  = eid;
				//click
				el_div.addEventListener('click', function(e) {
					Andrew_Ryan_guidestar_stats__scrapeGuidestarProfile(this);
					e.preventDefault();
					e.stopPropagation();
					return false;
				}, false);
				//mouseover
				el_div.addEventListener('mouseover', function() {
					var x = document.getElementsByTagName('div');
					for (var j in x) {
						if (j == 'length') break;
						if (x[j].className == this.className) {
							x[j].style.backgroundColor = 'LightGreen';
						} else if (!x[j].isClicked) {
							x[j].style.backgroundColor = '#eee';
						}
					}
					// Could do this also! .getElementsByClassName('class_');
				}, false);
				//mouseout
				el_div.addEventListener('mouseout', function() {
					var x = document.getElementsByTagName('div');
					for (var j in x) {
						if (j == 'length') break;
						if (x[j].className == this.className && !x[j].isClicked) {
							x[j].style.backgroundColor = '#eee';
						}
					}
					// Could do this also! .getElementsByClassName('class_');
				}, false);
				
				//~ var el_inp = document.createElement('input');
				//~ el_inp.setAttribute('style','width:auto;');
				//~ el_inp.setAttribute('type','button');
				//~ el_inp.value = rs[i][0]; // x
				//~ el_inp.onclick = function(e) {
					//~ this.style.backgroundColor = 'LightGreen';
					//~ //ELEMENT_OUT.value = this.value;
					//~ //ELEMENT_OUT.focus();
					//~ //doSubmit();
					//~ d2.src = this.value;
					//~ e.preventDefault();
					//~ e.stopPropagation();
					//~ return false;
				//~ }
				//~ el_div.appendChild(el_inp);
				
				var el_p = document.createElement('p');
				el_p.innerHTML = rs[i][0]; // YAHOO LINK !!!
				el_div.appendChild(el_p);
				
				var el_a = document.createElement('a');
				el_a.setAttribute('style','width:auto;');
				el_a.setAttribute('type','button');
				el_a.innerText = ' L ';
				el_a.target = '_blank';
				el_a.href = rs[i][0]; // full href!
				el_p.appendChild(el_a); // APPEND TO P !!
				
				var el_p = document.createElement('p');
				el_p.innerHTML = rs[i][1]; // YAHOO TEXT RESULT !!!
				el_div.appendChild(el_p);
				
				// container
				out_div.appendChild(el_div);
			}
			
			if (rs.length > 0) {
				var el = document.createElement('div');
				el.setAttribute('style','height:1200px;');
				out_div.appendChild(el);
			} else {
				out_div.innerText = d2.value + "\n" + '0 results';
				
				// do iframe search!
				//Andrew_Ryan_guidestar_stats__gsIframeSearch();
				d4.click();
			}
		}
