						x.setAttribute('style','width:79%;height:120px;zoom:0;cursor:pointer;');
						x.value = item.title[0];
						x.price = Math.round(price.trim().replace(/^([^ ]+)[^$]*$/, '$1') * 1);
						x.value = price + "\n" + condition + "\n" + item.title[0];
						x.onclick = function() {
							this.style.backgroundColor = 'LightGreen';
							q[0].value = this.price;
							//~ if (/^http:\/\/www\.ebay\.com\/itm\//.exec(this.id)) {
								//~ doSubmit();
							//~ }
						}
						d1.appendChild(x);
						x.readOnly = true;
						
