			//http://www.marktplaats.nl/z.html?categoryId=97&priceFrom=&priceTo=&yearFrom=2002&yearTo=2010&mileageFrom=&mileageTo=&attributes=S%2C473&startDateFrom=always
			
			// THIS WILL TRY 4 DIFFERENT METHODS TO FIND
			// A MATCHING CAR. IF TRY == 0 THEN THIS IS
			// THE MOST PREFERRED METHOD TO FINDING A CAR.
			// ELSE TRY FOR SECONDARY PREFERENCE.
			var year_from;
			var year_to;
			var benzine;
			
			switch(num_tries) {
				case 0: // year-exact + benzine
					year_from	= 2006;
					year_to		= 2010;
					benzine = '&attributes=S%2C473';
					break;
				case 1: // year-any + benzine
					year_from	= 1990;
					year_to		= 2014;
					benzine = '&attributes=S%2C473';
					break;
				case 2: // year-exact
					year_from	= 2006;
					year_to		= 2010;
					benzine = '';
					break;
				case 3: // neither !
					year_from	= 1990;
					year_to		= 2014;
					benzine = '';
					break;
			}
			//~ var year = (num_tries == 0) ? 2010 : 2014;
			
			//~ // UPDATE GLOBAL!
			//~ found_mk_model.mk		= id;
			//~ found_mk_model.model	= model;
			
