						r2 = /<span data-url="([^"]+)" class="thumb-placeholder-rectangular juiceless-link" title="([^"]+)"[\r\n\t\s]*style="background-image: url\('(\/\/[^']+)'\);"/.exec(m[1]);
						
						//~ console.log(r2);
						
						if (r2)
							urls_to_try.push(__js_clean_html_str(r2[1]).trim());
