						tmp += '<br>likes:<b>'+r[i].likes+'</b>';
						tmp += '<br>talking_about_count:'+r[i].talking_about_count;
						// loc
						if (r[i].location) {
							for (var j in r[i].location) {
								if (r[i].location[j].length > 0)
									tmp += '<br>' + MT__bold(r[i].location[j], o.location_array);
							}
						}
						// cat
						if (r[i].category) {
							var x = r[i].category;
							tmp += '<br>'+x;
						}
						tmp += '<br>' + r[i].link;
						// innerHTML
						div.innerHTML = tmp;
