		function Scott_Neufeld_places_search() {
			
			d1.innerHTML = '';
			//this.style.backgroundColor = 'LightGreen';
			
			var rf = new AMT___requests_factory();
			rf.database__select(
				{
					query: 'AMT_Requester__Scott_Neufeld',
					encodeStrings: [d2.value, o.state] // COMP. NAME, STATE
				},
				Scott_Neufeld_places_search__process
			);
		}
