		function Jason_Droege_edmunds_autos() {
			
			//http://www.edmunds.com/api/vehicle/v2/Mazda/models?fmt=json&state=new&view=full
			//var u = 'http://www.edmunds.com/api/vehicle/v2/'+encodeURIComponent(d2.value)+'/models?fmt=json&state=new&view=full'
			var u = 'http://www.edmunds.com/api/vehicle/v2/'+encodeURIComponent(d2.value)+'/models?fmt=json&state=used&view=full'
			
			var tmp_make  = d2.value;
			var tmp_model = d2b.value;
			
			GM_xmlhttpRequest({
				method: 'GET',
				url: MT___host + '/mturk/util.php?AMT__output_html_from_URL='+encodeURIComponent(u),
				onload: function (response) {
					var rs = response.responseText;
					
					if (response.status != 200) {
						exit(response.status);
					}
					
					rs = JSON.parse(rs);
					
					console.log(rs);
					
					if (!rs.models) {
						d1.innerText = '0';
						return;
					}
					
					var m;
					var found_model = false;
					var el_div;
					
					for (var i in rs.models) {
						m = rs.models[i];
						
						el_div = document.createElement('div');
						el_div.setAttribute('style', 'border-bottom:1px solid #a2a2a2;');
						el_div.innerText = m.name + "\n" + '';
						el_div.niceName = m.niceName;
						el_div.make = tmp_make.toLowerCase(); // ?
						el_div.year_id = false;
						el_div.obj_all_models = m;
						
						console.log(m.years);
						for (var j in m.years) {
							//~ if (!m.years) break;
							//~ if (!m.years[j]) break;
							var mys = m.years[j];
							if (mys.year == 2012) {
								//// NOT THIS!! //// el_div.year_id = m.years[j].id;
								
								//styles: Array[7]
								//0: Object
								//id: 200462904
								if (mys.styles && mys.styles[0] && mys.styles[0].id) {
									el_div.year_id = mys.styles[0].id;
								}
								break;
							}
						}
						
						if (!el_div.year_id)
							el_div.style.backgroundColor = 'aqua';
							
						el_div.onclick = Jason_Droege_edmunds_autos__prof;
						//~ el_div.onclick = function() {
							//~ if (!el_div.year_id) {
								//~ return;
							//~ }
							//~ // here?
							//~ Jason_Droege_edmunds_autos__prof(this);
						//~ }
						
						d1.appendChild(el_div);
						
						if (m.name == tmp_model && el_div.year_id) {
							found_model = true;
							el_div.click();
							break;
						}
					}
				}
			});
		}
