		// Function 
		function turk_HPCBeauty_amazon_units__appendTxt(div, text, out_inp, isHighlighted) {
			
			var x = document.createElement('div');
			x.setAttribute('style', 'display:block;');
			
			// MAKE BUTTONS
			
			// array of returned buttons
			var return_buttons_array = [];
			
			var text = text.split(' ');
			for (var i in text) {
				
				var btn = document.createElement('button');
				btn.setAttribute('style', 'border:0;margin:0;margin-right:2px;');
				
				// isHighlighted
				if (isHighlighted)
					btn.style.border = '2px solid teal';
				
				btn.innerText = text[i];
				
				if (text[i] == '<Size>') {
					btn.style.borderStyle = 'double';
					btn.style.borderWidth = '4px';
					//~ btn.style.borderStyle = 'dashed';
				}
				
				btn.out_inp = out_inp;
				//~ x.out_val = n[0].trim();
				
				//onclick
				btn.onclick = function(e) {
					//~ this.style.backgroudColor = '#000000'; // Does not work!!!
					this.style.border = '4px solid teal'; //
					//~ this.out_inp.value = this.innerText.replace(/[^\d\.]/g, '');
					
					var n = this.innerText.replace(/[^\d\.]/g, '') * 1;
					
					if(this.out_inp.value == '')
					{
						this.out_inp.value = n;
					}
					else
						this.out_inp.value = (Number(n)) 
											 * (Number(this.out_inp.value.replace(/[^\d\.]/g,'')));
					
					this.out_inp.value = this.out_inp.value.replace(/(\.[^0]*)[0]{2,}[\d]*$/,'$1');
					this.out_inp.value = this.out_inp.value.replace(/\.$/,''); // TRAILING PERIOD!
					
					this.out_inp.focus();
					this.out_inp.select();
					
					e.preventDefault();
					e.stopPropagation();
					return false;
				}
				//ondblclick
				btn.ondblclick = function(e) {
					//~ this.style.backgroudColor = '#000000'; // Does not work!!!
					this.style.border = '4px solid teal'; //
					//~ this.out_inp.value = this.innerText.replace(/[^\d\.]/g, '');
					
					var n = this.innerText.replace(/[^\d\.]/g, '') * 1;
					
					this.out_inp.value = n;
					
					this.out_inp.focus();
					this.out_inp.select();
					
					e.preventDefault();
					e.stopPropagation();
					return false;
				}
				
				x.appendChild(btn);
				
				return_buttons_array.push(btn);
			}
			
			//~ x.innerText = text;
			//~ 
			//~ var n = /[\d][\d,\. ]+/.exec(text); // init \d
			//~ if (n) {
				//~ x.style.cursor = 'pointer';
				//~ x.out_inp = out_inp;
				//~ x.out_val = n[0].trim();
				//~ x.onclick = function() {
					//~ this.style.backgroudColor = 'LightGreen';
					//~ this.out_inp.value = this.out_val;
				//~ }
			//~ }
			
			div.appendChild(x)
			
			//~ div.appendChild(document.createElement('br'));
			
			return return_buttons_array;
		}
