							var div_btns2 = document.createElement('div');
							var div_btns3 = document.createElement('div');
							
							div_container.appendChild(div_btns1);
							div_container.appendChild(div_btns2);
							div_container.appendChild(div_btns3);
							
							td.appendChild(div_container);
							
