		function Bart_Jansen_package_trackr__packagrtrackr__makeDate(month, day, el) {
			var m;
			switch(month) {
				case 'March':
					m = '3';
					break;
				case 'April':
					m = '4';
					break;
				case 'May':
					m = '5';
					break;
				default:
					exit('err month');
			}
			if (day*1 < 10 && day[0] != '0')
				day = '0' + day;
			el.value = '0'+m+'/'+day+'/2014';
			//return '0'+m+'/'+day+'/2014';
		}
