		function Yogesh_K_Riyat_capsuleshow_com() {
			GM_xmlhttpRequest({
				method: 'GET',
				url: d2.value,
				onload: function (response) {
					var rs = response.responseText;
					
					if (response.status > 200) {
						exit(response.status);
					}
					
					var r;
					var sbm = true;
					
					// build contacts
					r = /<h6>([^:]+):<\/h6>[\r\n\t\s]+((.|\s)*?(?=<h6>|$)|$)/g;
					var m;
					var contacts = [];
					while (m = r.exec(rs)) {
						//m[1] is unimportant
						
						var x = {name: '', email: ''};
						
						m[2] = m[2].trim();
						
						var y = /^<p class="no-marg-bottom">([^<]+)<\/p>/.exec(m[2]);
						if (y) {
							x.name = __js_clean_html_str(y[1]).trim();
						}
						var y = /<strong>([^<]+)<\/strong>/.exec(m[2]);
						if (y) {
							x.email = __js_clean_html_str(y[1]).trim();
						} else
							x.email = 'N/A';
						
						contacts.push(x);
					}
					console.log(contacts);
					
					// fill in
					var usedPpl = [];
					var usedPpl_hash = [];
					// fill in best
					var count = 1;
					for (var i in contacts) {
						if (count >= 3) break;
						var clnName = contacts[i].name.toLowerCase().replace(/[^\w\d]/g, '');
						var hash = clnName+contacts[i].email;
						if  (
							contacts[i].name.length >= 1 &&
							contacts[i].email.length >= 1 &&
							contacts[i].email.indexOf('@') != -1 &&
							!__js_inarray(usedPpl, clnName)
							)
						{
							document.getElementsByName('ContactName'+ count)[0].value = contacts[i].name;
							document.getElementsByName('Email'+ count)[0].value = contacts[i].email;
							usedPpl.push(clnName);
							if (contacts[i].email != 'N/A')
								usedPpl_hash.push(hash);
							count++;
						}
					}
					// fill in "rest"
					if (count != 3) {
						for (var i in contacts) {
							if (count >= 3) break;//console.log(count);
							var clnName = contacts[i].name.toLowerCase().replace(/[^\w\d]/g, '');
							if  (
								contacts[i].name.length >= 1 &&
								!__js_inarray(usedPpl, clnName)
								)
							{
								document.getElementsByName('ContactName'+ count)[0].value = contacts[i].name;
								document.getElementsByName('Email'+ count)[0].value = contacts[i].email;
								usedPpl.push(clnName);
								count++;
							}
						}
					}
					// else fill in dup?
					if (count != 3) {
						for (var i in contacts) {
							if (count >= 3) break;
							var clnName = contacts[i].name.toLowerCase().replace(/[^\w\d]/g, '');
							var hash = clnName+contacts[i].email;
							if  (
								contacts[i].name.length >= 1 &&
								contacts[i].email.indexOf('@') != -1 &&
								!__js_inarray(usedPpl_hash, hash)
								)
							{
								document.getElementsByName('ContactName'+ count)[0].value = contacts[i].name;
								document.getElementsByName('Email'+ count)[0].value = contacts[i].email;
								usedPpl.push(clnName);
								if (contacts[i].email != 'N/A')
									usedPpl_hash.push(hash);
								count++;
								//sbm = false;// !
							}
						}
					}
					
					// website
					var x = /<li><a href="([^"]+)" target="_blank"><i class="fa fa-dot-circle-o"><\/i>/.exec(rs);
					if (x && x[1].length >= 4) {
						document.getElementById('Field5').value = __js_clean_html_str(x[1]);
						if (x[1].length < 6)
							sbm = false;
					} else {
						document.getElementById('Field5').value = 'N/A';
					}
					
					if (count != 3) {
						for (var i = count; i <= 2; i++) {
							document.getElementsByName('ContactName'+ i)[0].value = 'N/A';
							document.getElementsByName('Email'+ i)[0].value = 'N/A';
						}
						//sbm = false;
					}
					
					console.log(sbm);
					if (sbm) {
						doSubmit();
					}
				}
			});
		}
