		function Nik_Patel_truefabrications__prof(u) {
			GM_xmlhttpRequest({
				method: 'GET',
				url: u,
				onload: function (response) {
					var rs = response.responseText;
					
					if (response.status > 200) {
						exit(response.status);
					}
					
					
					var r;
					var sbm = true;
					
					r = /PRODUCT INFORMATION([\r\n\t\s]+|<span[^>]*>|<p[^>]*>|<\/p[^>]*>)*([^<]+)(<\/span>|[\r\n\t\s]+|<br *\/>)*/.exec(rs);
					if (r) {
						console.log(r);
						var x = __js_clean_html_str(r[2]).trim();
						q[0].value = x;
						if (x == '')
							sbm = false;
					} else {
						sbm = false;
					}
					
					r = /PRODUCT INFORMATION<\/p>((.|\s)*?(?=<\/ul>|$)|$)/.exec(rs);
					if (r) {
						
						r = r[1];
						
						var r2 = /<li[^>]*>((.|\s)*?(?=<\/li>|$)|$)/gi;
						var m;
						var c = 1;
						var x;
						while (m = r2.exec(r)) {
							if (c >= 5)
								break;
							x = m[1];
							x = x.replace(/<[^>]*>/g, '');
							if (/[<>]/.exec(x)) {
								sbm = false;
								continue;
							}
							x = __js_clean_html_str(x).trim().replace(/\s+/g, ' ');
							q[c].value = x;
							if (x == '')
								sbm = false;
							c++;
						}
						if (c == 1)
							sbm = false;
					} else {
						sbm = false;
					}
					//
					console.log(sbm);
					if (sbm) {
						doSubmit__serverSide();
					} else {
						document.body.style.border = '6px solid blue';
					}
					
					
				}
			});
		}
