		function Raymond_Fong_Google() {
			GM_xmlhttpRequest({
				method: 'GET',
				url: url,
				onload: function (response) {
					var rs = response.responseText;
					
					if (response.status > 200) {
						document.body.style.backgroundColor = 'pink';
						return;
					}
					
					var r;
					r = /<h3 class="r"><a href="([^"]+)((.|\s)*?(?=<!--n-->|$)|$)/g;
					var count = 0;
					if (r.exec(rs)) {
						r.lastIndex = 0;
						var c = 1;
						var sbm = true;
						while (m = r.exec(rs)) {
							
							m[1] = __js_clean_html_str(m[1]);
							
							//if (/^https?:\/\/([^\.]+\.|)google\./i.exec(m[1]))
							//	continue;
							
							// replace "harm your comp."
							m[1] = m[1].replace(/^\/interstitial\?url=/, '');
							
							// google.com
							if (/^\//i.exec(m[1]))
								continue;
								
							document.getElementById('Field'+c).value = m[1];
							if (!/https?:\/\/[^\/]{6,}/.exec(m[1])) {
								sbm = false;
							}
							
							//break; // ENDS HERE
							c++;
							
							if (c >= 8) // 1...7
								break;
						}
						
						console.log(c);
						console.log(sbm);
						if (c == 8 && sbm) {
							doSubmit();
							//doSubmit__serverSide();
						}
					}
				}
			});
		}
