					// student
					r = /<dt class="phonebook"  title="[^"]+">([^<]+)<span>([^<]+)<\/span>[\r\n\t\s]+<\/dt>[\r\n\t\s]+<dd>[\r\n\t\s]+<p>((.|\s)*?(?=<\/p>|$)|$)/g;
