						tmp_em = __js_clean_html_str(r2[2]).trim();
						tmp_ph = __js_clean_html_str(r2[4]).trim();
						
						if (tmp_em == 'no email address provided')
							tmp_em = 'N/A';
						if (tmp_ph == '')
							tmp_ph = 'N/A';
