		// skip
		//keydown
		window.addEventListener('keydown',function(e) {
			var k = e.keyCode;
			console.log(k);
			
			var x = document.getElementById('lawmaker_name');
			
			if (k >= 96 && k<=103) { //101 is last
				var i = Math.round(k*1 - 96);
				document.getElementById('sked').selectedIndex = i;
				e.stopPropagation();
				e.preventDefault();
				
				var x = document.getElementById('lawmaker_name');
				x.value = x.value.trim();
				if (x.value != '') {
					//doSubmit();
					Center_for_Investigative_Reporting__write(true);
				}
					
				return false;
			}
			if (k == 107) { // +
				document.getElementById('cover_page_yes').checked = true;
				document.getElementById('cover_page_no').checked = false;
				document.getElementById('sked').selectedIndex = 0;
				e.stopPropagation();
				e.preventDefault();
				
				
				x.value = x.value.trim();
				if (x.value != '') {
					Center_for_Investigative_Reporting__write(true);
				}
					
				return false;
			}
			
			// on backslask do iterate through autofill 
			if (k == 220) {
				if (d1.length != 0) {
					if (d1.selectedIndex == -1) { // -1 == none selected
						d1.selectedIndex = 0;
					}
					else {
						if (d1.selectedIndex+1 >= d1.length)
							d1.selectedIndex = 0;
						else
							d1.selectedIndex++;
					}
					
					if (d1.value != '')
						x.value = d1.value;
				}
				
				e.stopPropagation();
				e.preventDefault();
				return false;
			}
		}, true);
		
