					'O:'+yp_order_online+""
					
					//~ 'P:'+ypprc+"<br>"+
					//~ 'C:'+ypcat+"<br>"+
				;
				el_div.yelp_url = ypurl;
				el_div.yp_order_online = yp_order_online;
