						r = /<span class="category-str-list">((.|\s)*?(?=<\/span>|$)|$)/.exec(k);
						if (r) {
							r = r[1];
							r = r.replace(/<[^>]+>/g, '');
							r = __js_clean_html_str(r);
							r = r.replace(/\s+/g, ' ').trim();
							ypcat = r;
						}
						//
						var ypprc = '';
						r = /<span class="business-attribute price-range">([\$£]+)/.exec(k);
						if (r) {
							r = r[1];
							r = r.length; //$$ = 2 OR £
							if (r < 1 || r > 4)
								alert('$' + r.length);
							ypprc = r;
						}
						//
						var ypnhd = '';
						r = /<span class="neighborhood-str-list">([^<]+)<\/span>/.exec(k);
						if (r) {
							r = r[1];
							r = r.replace(/<[^>]+>/g, '');
							r = __js_clean_html_str(r);
							r = r.replace(/\s+/g, ' ').trim();
							ypnhd = r;
						}
						
