		function Natalia_Kogay_yelp(first) {
			
			u = 'http://www.yelp.com/search/snippet'+
					'?find_desc='+encodeURIComponent(d2.value) +
					'&find_loc='+ encodeURIComponent(d2b.value)+
					//'&cflt=restaurants'+
					'&parent_request_id=&request_origin=user';
					
			if (first) {
				u += '&attrs=RestaurantsReservations';
				d1.innerHTML = '';
				// reset all array
				all_pages = [];
			}
			else {
				
			}
			
			GM_xmlhttpRequest({
				method: 'GET',
				url: u,
				onload: function (response) {
					var rs = response.responseText;
					
					if (response.status != 200) return;
					
					rs = JSON.parse(rs);
					
					console.log(rs);

					if (!rs.search_results)
						return;
					if (!rs.search_map)
						return;
					
					var map = rs.search_map;
					
					rs = rs.search_results;
					
					var r;
					var m;
					var found = false;
					var c = 0;
					var name_m2;
					var r2;
					var addr;
					var num;
					
					r = /<h3 class="search-result-title">((.|\s)*?(?=<h3 class="search-result-title">|$)|$)/g;
					
					if (first && !r.exec(rs)) {
						FIRST_RESULTS_NUM = 0;
					} else if (first)
						FIRST_RESULTS_NUM = 1;
					//console.log(FIRST_RESULTS_NUM);
					
					r.lastIndex = 0;
					while (m = r.exec(rs)) {
						r2 = /<span class="indexed-biz-name">(\d+)\.[\t\s]+<a class="biz-name" href="([^"]+)"[^>]*>((.|\s)*?(?=<\/a>|$)|$)/.exec(m[1]);
						if (!r2) continue;
						
						//z[j].innerHTML = 'âœ“';
						//z[j].style.fontWeigt = 'bold';
						
						r2[2] = r2[2].replace(/#[\d\D]+$/, '')
						
						if (!first) {
							if (__js_inarray(all_pages, r2[2])) {
								r2[3] = '•'; //
							}
						}
						else {
							all_pages.push(r2[2]);
						}
						
						// name
						r2[3] = r2[3].replace(/<[^>]+>/g, '');
						
						
						num = Math.round(r2[1]*1); // for map
						
						// addr //xx
						addr = /<address>[\r\n\t\s]+((.|\s)*?(?=<\/address>|$)|$)/.exec(m[1]);
						if (addr) {
							addr = addr[1].replace(/<[^>]*>/g, '').trim();
						} else
							addr = '';
						//
						if  (
							map.center &&
							map.markers[num]
							)
						{
							addr = Math.round(MT___lat_lng_distance(
								map.center.latitude,
								map.center.longitude,
								map.markers[num].location.latitude,
								map.markers[num].location.longitude
							));// + ' ' + addr; //mi
						}
						else
						{
							addr = '';
						}
						
						
						d1.innerHTML += '\
							<p style="border-bottom:2px solid #3a3a3a;">\
								'+addr+' '+r2[3]+'\
							</p>\
						';
						
						if (!found) { // NO CLOSED/MOVED
							console.log(name_m);
							console.log(name_m2);
							name_m2 = r2[3].toLowerCase().trim().replace(/[^\w\d_]/g, '');
							if (first) { // FIRST
								if (name_m2 == name_m && name_m.length >= 4) {
									var x = d1.getElementsByTagName('p');
									x[x.length - 1].style.backgroundColor = 'LightGreen';
									found = true;
									document.getElementById('Q1Url').value = 'Yes';
									doSubmit();
								}
							} else if (FIRST_RESULTS_NUM == 0) {
								if (name_m2 == name_m && name_m.length >= 4 && c == 0) { // only #0
									var x = d1.getElementsByTagName('p');
									x[x.length - 1].style.backgroundColor = 'LightGreen';
									found = true;
									document.getElementById('Q1Url').value = 'No';
									doSubmit();
								}
							}
						}
						c++;
					}
					
					if (c == 0) {
						d1.innerHTML += '0';
					}
					
					if (!found && first) {
						d1.innerHTML += '<hr style="border-bottom:5px solid #3aae3a;">';
						Natalia_Kogay_yelp(false);
						return;
					}
					
					if (!first) { //end
						d1.innerHTML += '<div style="height:1400px;">&nbsp;</div>';
					}
					
				}
			});
		}
		
