		// ...
		function Rich_Gentry_zoominfo_people() {
			d1.innerHTML = '';
			
			var data = '{"boardMember":{"value":"Include","isUsed":true},"workHistory":{"value":"CurrentAndPast","isUsed":true},"includePartialProfiles":{"value":true,"isUsed":true},"personName":{"value":"'+encodeURIComponent(d2.value)+'","isUsed":true},"companyName":{"value":"'+encodeURIComponent(d3.value)+'","isUsed":true},"lastUpdated":{"value":0,"isUsed":true}}';
			
			var u = 'http://www.zoominfo.com/s/search/person?criteria='+encodeURIComponent(data);
			
			// AND A GET !
			GM_xmlhttpRequest({
				method: "GET",
				url: MT___host + '/mturk/util.php?AMT__output_html_from_URL='+encodeURIComponent(u),
			//~ GM_xmlhttpRequest({
				//~ method: "POST",
				//~ url: 'http://www.zoominfo.com/s/search/person',
				//~ data: 'criteria='+encodeURIComponent(data),
				//~ headers: {
					//~ "Content-Type": "application/x-www-form-urlencoded"
				//~ },
				onload: function(response) {
					var rs = response.responseText;
					
					if (response.status != 200) {
						d1.innerHTML = response.status;
						return;
					}
					
					//document.body.innerHTML = rs;
					//d1.innerHTML = rs;
					var r;
					
					r = /<tr>((.|\s)*?(?=<\/tr>|$)|$)/g;
					
					// ...
					if (r.exec(rs)) {
						var num = rs.match(r).length * 1;
						//~ d1.innerText = num + '\n';
						var d = document.createElement('div');
						d.setAttribute('style', 'border-bottom:1px solid #a2a2a2;');
						d.innerText = o.nm + '\n' + o.comp + '\n' + num + '\n';
						d1.appendChild(d);
					}
					
					// ...
					r.lastIndex = 0;
					
					var skip_allowed = true;
					if (num <= 2)
						skip_allowed = false;
					
					// ...
					var m;
					var r_nm,r_id,r_title,r_comp;
					var da,db,inp,ifrm;
					var auto  = false;
					var first = true;
					var cln;
					while (m = r.exec(rs)) {
						
						// ...
						r_nm	= /<a href="\/s\/#!search\/profile\/person\?personId=([\d\-]+)[^>]+>([^<]+)<\/a>/.exec(m[1]);
						//r_nm	= /<a href="#" id="p_([\d]+)" title="([^"]*)" class="checkbox unchecked">/.exec(m[1]);
						if (r_nm) {
							r_id = r_nm[1];
							r_nm = __js_clean_html_str(r_nm[2]).trim();
							r_nm = (r_nm == 'Phone') ? '' : r_nm;
							r_nm = MT__bold(r_nm, o.nm.split(' '));
						} else { // THIS IS JUST AN OUTLYING <TD>!!
							//console.log('null');
							continue;
						}
						
						// ...
						r_title	= /<input type="hidden" name="" value="([^"]*)" id="personTitle"\/>/.exec(m[1]);
						if (r_title) {
							r_title = __js_clean_html_str(r_title[1]).trim();
						} else r_title = '';
						
						// ...
						r_comp	= /<div class="companyLink">((.|\s)*?(?=<\/div>|$)|$)/.exec(m[1]);
						if (r_comp) {
							r_comp = r_comp[1].replace(/<[^>]*>/g, '');
							r_comp = __js_clean_html_str(r_comp).trim();
							r_comp = MT__bold(r_comp, o.comp.split(' '));
						} else r_comp = '';
						
						// ...
						da = document.createElement('div');
						db = document.createElement('div');
						inp = document.createElement('input');
						ifrm = document.createElement('iframe');
						
						// ...
						da.setAttribute('style', 'border-bottom:1px solid #a2a2a2;');
						da.className = 'div-zi';
						da.r_id = r_id;
						da.r_comp = r_comp;
						da.onclick = function() {
							this.style.backgroundColor = 'LightGreen';
							document.getElementsByName('Q5FreeTextInput')[0].value = 'http://www.zoominfo.com/s/#!search/profile/person?personId='+this.r_id+'&targetid=profile';
							doSubmit();
						}
						
						// ...
						inp.value = r_id;
						inp.r_ifrm = ifrm;
						inp.r_skip_allowed = skip_allowed;
						inp.setAttribute('type', 'button');
						inp.onclick = function(e) {
							Rich_Gentry_zoominfo_people__profile(this);
							e.stopPropagation();
							e.preventDefault();
							return false;
						}
						
						// ...
						db.innerHTML = r_nm + '<br>' + r_comp + '<br>' + r_title + '<br>';
						
						// ...
						ifrm.setAttribute('style', 'width:100%;height:10px;');//zoom:0.6;
						ifrm.className = 'ifrm-zi';
						
						// ...
						da.appendChild(db);
						da.appendChild(inp);
						da.appendChild(ifrm);
						
						d1.appendChild(da);
						
						// auto?
						cln = m[1].replace(/[^\w]/g, '').toLowerCase();
						//~ console.log(o.nm_cln);
						//~ console.log(o.comp_cln);
						if  (
							!auto &&
							first &&
							cln.indexOf(o.nm_cln	) != -1 &&
							cln.indexOf(o.comp_cln	) != -1 &&
							o.nm_cln.length		> 6 &&
							o.comp_cln.length	> 6
							)
						{
							auto	= true;
							first	= false;
							da.click();
						} else if (first) { // click first always
							first	= false;
							inp.click();
						}
						
						// exact name
						if  (
							cln.indexOf(o.nm_cln) != -1 &&
							o.nm_cln.length	> 6
							)
						{
							inp.nm_match = true;
							console.log('nm true');
						} else {
							inp.nm_match = false;
							console.log('nm false');
						}
					}
					
					
					// THERE ARE RESULTS!
					if (num <= 2) {
						if (AMT__Global_Vars.isPreview)
							AMT___Floater.accept();
						return;
					}
					//~ if (num > 4 && !auto) {
						//~ d1.innerHTML = '';
						//~ 
					//~ }
						
					if (d1.innerHTML.trim() == '' || d1.innerHTML.trim() == '0') {
						d1.innerHTML = rs;
						
						Rich_Gentry_zoominfo_people__nextSearch();
					} else {
						var d = document.createElement('div');
						d.setAttribute('style', 'height:2000px;');
						d1.appendChild(d);
						
						//
					}
					
				}
			});
		}
		
		// ...
		function Rich_Gentry_zoominfo_people__nextSearch() {
			// do search again !!
			if (number_of_auto_tries == 0) {
				number_of_auto_tries = 1;
				//~ var x = d2.value.split(' ');
				//~ if (x.length > 2) {
					//~ // do below
				//~ } else {
					//~ number_of_auto_tries = 1; // go to 1 !
				//~ }
			}
			
			console.log('number_of_auto_tries:'+number_of_auto_tries);
			
			if (number_of_auto_tries == 0) {
				//~ number_of_auto_tries = 1;
				//~ var x = d2.value.split(' ');
				//~ if (x.length > 2) {
					//~ d2.value = x[0] + ' ' + x[x.length -1]; // f, l
					//~ d2.style.border = '4px solid LightGreen';
					//~ setTimeout(Rich_Gentry_zoominfo_people, 600);
				//~ }
			} else if (number_of_auto_tries == 1) {
				// FULL NAME
				// FIRST LETTER COMP.
				number_of_auto_tries = 2;
				var x = /^(.{3}[^ ]*)[^$]+/.exec(d3.value); // ^XXX xyz$, Any characters 3, 0 or more of non-space chars., (end capture), not end of string 1 or more
				if (x) {
					d3.value = x[1];
					d3.style.border = '4px solid LightGreen';
					setTimeout(Rich_Gentry_zoominfo_people, 600);
				}
			} else if (number_of_auto_tries == 2) {
				// FULL NAME
				// X COMP.
				number_of_auto_tries = 3;
				var x = /^(.{3}[^ ]*)[^$]+/.exec(d3.value); // ^XXX xyz$, Any characters 3, 0 or more of non-space chars., (end capture), not end of string 1 or more
				d2.value = o.nm;
				d3.value = '';
				setTimeout(Rich_Gentry_zoominfo_people, 600);
			} else if (number_of_auto_tries == 3) {
				// NO MIDDLE NAME
				// X COMP.
				number_of_auto_tries = 4;
				var x = d2.value.split(' ');
				if (x.length > 2) {
					d2.value = x[0] + ' ' + x[x.length -1]; // f, l
					d2.style.border = '4px solid LightGreen';
					setTimeout(Rich_Gentry_zoominfo_people, 600);
				} else { // SKIP!
					if (AMT__Global_Vars.isPreview) {
						AMT___Floater.skip();
					}
				}
			}
			
			// THERE ARE NO RESULTS AND NO MORE SEARCHES!
			else {
				if (AMT__Global_Vars.isPreview) {
					AMT___Floater.skip();
				}
			}
		}
		// ...
		function Rich_Gentry_zoominfo_people__profile(btn) {
			
			var u = 'http://www.zoominfo.com/s/search/profile/personpopup?personId='+encodeURIComponent(btn.value)+'&targetid=profile';
			
			var btn = btn;
			
			var skip_allowed = skip_allowed;
			
			GM_xmlhttpRequest({
				method: "GET",
				url: MT___host + '/mturk/util.php?AMT__output_html_from_URL='+encodeURIComponent(u),
				onload: function(response) {
					var rs = response.responseText;
					
					if (response.status != 200) {
						d1.innerHTML = response.status;
						return;
					}
					
					// fill parentNode
					//btn.parentNode.innerHTML = rs.replace(/<script[^$]*/, '');
					
					//rs = rs.replace(/&amp;/gi, '&');
					rs = rs.replace(/(&[\w#\d]+;)/gi, function(p0, p1) {
						return __js_clean_html_str(p1);
					});
					
					var rs_original = rs;
					
					// name
					var n = /<input type="hidden" id="personName" value="[^"]*"><h1>[\r\n\t\s]*([^\r\n]*)/.exec(rs);
					n = (n) ? n[1] : '';
					
					var x = /^((.|\s)*?(?=<div class="intelius">[\r\n\t\s]+[^\r\n]*[\r\n\t\s]+<\/div>|$)|$)/.exec(rs);
					if (x) {
						rs = rs.replace(x[0], '');
						rs = '<body><div><div><div><div><div><div><div><div><div><div><div><div><div><div><div><div>' + n + rs;
					}
					
					rs = rs.replace(/<\/?(h|span|a|img|script|iframe|strong)[^>]*>/gi, '');
					rs = MT__bold(rs, o.comp.split(' '));
					rs = '<html><style type="text/css">body {zoom:0.7;height:4000px;}</style>' + rs;
					
					
					//~ rs = rs.split('<div class="intelius">');
					//~ if (rs.length > 1) {
						//~ rs = rs.slice(1).join('');
					//~ } else {
						//~ rs = rs.join('');
					//~ }
					
					var rf = new AMT___requests_factory();
					rf.io__AMT__displayPostStrAsHTML(
						rs,
						btn.r_ifrm
					);
					
					// hide other iframes
					// ifrm-zi
					var x = document.getElementsByClassName('ifrm-zi');
					for (var i in x) {
						if (i == 'length') break;
						x[i].style.height = '10px';
					}
					
					// ...
					btn.r_ifrm.style.height = '200px';
					
					// auto?
					var auto = false;
					if	(
						btn.nm_match &&
						o.comp_cln.length > 6 &&
						rs_original.replace(/[^\w]/g, '').toLowerCase().indexOf(o.comp_cln) != -1
						)
					{
						if (AMT__Global_Vars.isPreview) {
							AMT___Floater.accept();
							return;
						} else {
							auto = true;
							btn.parentNode.click();
							return;
						}
					}
					
					// Here?
					// btn.r_skip_allowed
					if (!auto && btn.r_skip_allowed) {
						Rich_Gentry_zoominfo_people__nextSearch();
					}
					
					//~ console.log(rs.replace(/[^\w]/g, '').toLowerCase().indexOf(o.comp_cln));
					//~ console.log(rs.replace(/[^\w]/g, '').toLowerCase());
					//~ console.log(o.comp_cln);
					
					//btn.r_ifrm.src = MT___host + '/mturk/util.php?AMT__displayGetStrAsHTML=' + encodeURIComponent(MT__bold(rs, o.comp.split(' ')));
					
					//~ if  (
						//~ (
							//~ new RegExp(__js_escape_regEx(d3.value),	'i').exec(rs) &&
							//~ d2.value.length	> 6
						//~ ) ||
						//~ (
							//~ new RegExp(__js_escape_regEx(o.nm),		'i').exec(rs) &&
							//~ o.nm.length		> 6
						//~ )
						//~ )
					//~ {
						//~ btn.parentNode.click();
					//~ } else {
						//~ // fill parentNode
						//~ btn.parentNode.innerHTML = rs.replace(/<script[^$]*/, '');
					//~ }
				}
			});
		}
