		function Brian_Diez_parse_geo(rs) {
			console.log(rs);
			try {
				//console.log(rs.results[0].address_components);
			} catch (e) {
				exit('parse geo'); // quit
			}
			
			d2d.value = rs.results[0].formatted_address;
			
			var x;
			//var found_st = false;
			var subpremise = false;
			var stringify = JSON.stringify(rs);
			for (var i in rs.results[0].address_components) {
				x = rs.results[0].address_components[i];
				if (x.types[0] == 'subpremise') {
					subpremise = true;
				}
				if (x.types[0] == 'street_number') {
					document.getElementsByName('Address')[0].value = x.short_name;
				}
				if (x.types[0] == 'route') {
					document.getElementsByName('Address')[0].value+= ' '+x.short_name;
				}
				if (x.types[0] == 'postal_code') {
					document.getElementsByName('Postal')[0].value = x.short_name;
					//if (x.short_name != x.long_name) {
					//	sbm = false;
					//	console.log('short long');
					//}
					//found = true;
					if (/[^\d]/.exec(x.short_name))
						sbm = false;
					if (x.short_name.length != 5)
						sbm = false;
					//break;
				}
				if (x.types[0] == 'locality') {
					document.getElementsByName('City')[0].value = x.short_name;
				}
				if (x.types[0] == 'administrative_area_level_1') { //STATE
					if (stringify.indexOf('United States') == -1) continue; //skip non-us
					for (var j in MT___states) { //abbr,full
						if  (
							MT___states[j] == x.short_name ||
							j == x.short_name
							) {
							document.getElementsByName('State')[0].value = j;//abbr
							break;
						}
					}
				}
				if (x.types[0] == 'country') {
					if (x.long_name != x.short_name && x.long_name.length >= 3) {
						document.getElementsByName('Country')[0].value = x.long_name;
					} else {
						for (var j in MT___countries) { //{.name,.code} 
							if (MT___countries[j].code == x.short_name) {
								document.getElementsByName('Country')[0].value = MT___countries[j].name;
								break;
							}
						}
					}
				}
			}
			//trim route
			document.getElementsByName('Address')[0].value = document.getElementsByName('Address')[0].value.trim();
			//sub
			if (subpremise) {
				document.getElementsByName('Address')[0].style.border = '4px solid blue';
			}
		}
