		function Evan_Hanson_find_address_phone() {
			
			d1.innerHTML = '';
			
			// 2
			var u;
			u = 'https://maps.googleapis.com/maps/api/place/textsearch/json?';
			u+= '&query=' + encodeURIComponent(d2.value);
			u+= '&sensor=false';
			u+= '&key=_GOOGLE_API_KEY_REDACTED_';
			
			GM_xmlhttpRequest({
				method: "GET",
				url: u,
				onload: function(response) {
					var rs = response.responseText;
					
					rs = JSON.parse(rs);
					
					console.log(rs);
					
					if (!rs.results) return;
					if (!rs.results.length) {
						d1.innerHTML = '0';
						return;
					}
					
					var x;
					var icon;
					var count = 0;
					var m_comp;
					//var m_city;
					var m_loc;
					
					var lt_ln;
					var location;
					for (var i in rs.results) {
						x = rs.results[i];
						
						//if (x.icon.indexOf('http://maps.gstatic.com/mapfiles/place_api/icons/') == -1) { //
						//	icon = '<br ><img src="'+x.icon+'" style="max-width:100px;">';
						//} else
						icon = '';
						
						lt_ln = '';
						try {
							if (x.geometry.location.lat)
								lt_ln = x.geometry.location.lat + ' ' + x.geometry.location.lng;
						} catch (e) {
							
						}
						location = '';
						m_loc = '';
						if (x.formatted_address) {
							location = '<br>'+x.formatted_address;
							m_loc = x.formatted_address;
						}
						
						d1.innerHTML += '\
						<div>\
						<input type="button" value="'+x.name+'" id="'+x.reference+'" class="exe" style="width:auto;text-align:left;">\
						<input type="hidden" value="'+m_loc+'" class="addr">\
							'+location+'\
							'+icon+'\
							<hr >\
						</div>\
							';
						
						if (count == 0) {
							m_comp = x.name.replace(/[^\d\w_]/g, '').toLowerCase();
							
							var comp = b[0].innerText.replace(/[^\d\w_]/g, '').toLowerCase();
							
							if  (
								comp.length >= 2 &&
								state.length >= 2 &&
								m_comp.length >= 2 &&
								m_loc.length >= 2 &&
								comp == m_comp &&
								m_loc.indexOf(state+', United States') != -1
								)
							{
								var y = d1.getElementsByTagName('input');
								y[y.length - 1].style.backgroundColor = 'LightGreen';
								q[0].value = m_loc;
								Evan_Hanson_find_address_phone_getProfile(x.reference);
							}
						}
						count++;
					}
					if (d1.innerHTML != '') {
						d1.innerHTML += '<div style="height:1200px;"></div>';
					}
					
					var x = document.getElementsByClassName('exe');
					for (var i in x) {
						if (!x[i]) continue;
						x[i].onclick = function() {
							this.style.backgroundColor = 'LightGreen';
							var i = this.parentNode.getElementsByClassName('addr')[0];
							q[0].value = i.value;
							Evan_Hanson_find_address_phone_getProfile(this.id);
							/*//var x = this.id.split('|');
							//if (x.length == 2 && /^([\-\d\.]+)\|([\-\d\.]+)\|([^\|]+)\|([^$]+)$/.exec(this.id)) {
							var x = /^([\-\d\.]+)\|([\-\d\.]+)\|([^\|]+)\|([^$]+)$/.exec(this.id);
							if (x) {
								q[0] = x[2];
								q[2] = x[0];
								q[3] = x[1];
								Evan_Hanson_find_address_phone_getProfile(x[3]);
							}*/
						}
					}
				}
			});
		}
