		function Matthew_Kennedy_LinkedInProfileAndEmployees__2() {
			
			var url;
			
			url = 'http://www.linkedin.com/vsearch/cj' +
				'?type=companies&keywords='+encodeURIComponent(d2.value)+
				'&orig=GLHD&rsid=&pageKey=voltron_company_search_internal_jsp';
			
			var out;
			out = d1;
				
			out.innerHTML = '';
			
			GM_xmlhttpRequest({
				method: 'GET',
				url: url,
				onload: function (response) {
					var rs = response.responseText;
					
					if (response.status > 200) {
						d1b.style.backgroundColor = 'blue';
						return;
					}
					
					var r;
					r = JSON.parse(rs);
					//console.log(r);
					
					if (r.content.page.voltron_unified_search_json.search.results_count_with_keywords_i18n)
						out.innerHTML += r.content.page.voltron_unified_search_json.search.results_count_with_keywords_i18n.replace(/<[^>]+>/g, '') + '<hr>';
					else
						out.innerHTML += r.content.page.voltron_unified_search_json.search.results_count_without_keywords_i18n.replace(/<[^>]+>/g, '') + '<hr>';
					
					var x = r.content.page.voltron_unified_search_json.search.results;
					
					var found = false;
					var x_;
					var btn;
					for (var i in x) {
						if (!x[i].company) continue;
						
						x_ = x[i].company;
						//console.log(x_);
						x_.fmt_canonicalName = x_.fmt_canonicalName.replace(/<[^>]+>/g, '');
						x_.fmt_canonicalName = __js_clean_html_str(x_.fmt_canonicalName);
						
						x_.fmt_size = (x_.fmt_size) ? x_.fmt_size : '0';
						x_.fmt_size = (x_.fmt_size == 'Myself Only') ? '1' : x_.fmt_size;
						
						var btn = document.createElement('button');
						btn.setAttribute('style','');
						btn.setAttribute('id',x_.id);
						//btn.setAttribute('id',x_.fmt_size);
						btn.onclick = function() {
							this.style.backgroundColor = 'LightGreen';
							//~ q.value = this.id;
							//~ if (q.value.length >= 1 && q.value != 'undefined')
								//~ doSubmit();
							Matthew_Kennedy_LinkedInProfileAndEmployees__prof__2(this.id);
						}
						btn.innerHTML = MT__bold(x_.fmt_canonicalName, COMP_ARR); // o = str, x = words to be bolded
						//btn.value = MT__bold(x_.fmt_canonicalName, COMP_ARR); // o = str, x = words to be bolded
						out.appendChild(btn);
						
						out.appendChild(document.createElement('br'));
						out.appendChild(document.createTextNode(x_.fmt_size));
						out.appendChild(document.createElement('hr'));
						
						if (!found) {
							found = true;
							if  (
								x_.fmt_canonicalName.replace(/[^\w\d]/g, '').toLowerCase()
									==
								COMP.replace(/[^\w\d]/g, '').toLowerCase()
								&&
								COMP.replace(/[^\w\d]/g, '').toLowerCase().length >= 4
								)
							{
								btn.click();
							}
						}
					}
				}
			});
		}
