	function sam_molyneux_journals_yahoo() {
		//><img src='http://ts
		var url;
		if (FIRST_RUN) {
			FIRST_RUN = false;
			url = 'http://images.search.yahoo.com/search/images?p='+encodeURIComponent(di.value)+'&ei=utf-8&fr=sfp-img&fr2=&y=Search';
		} else
			url = 'http://images.search.yahoo.com/search/images?p='+encodeURIComponent(di.value+' "dr."')+'&ei=utf-8&fr=sfp-img&fr2=&y=Search';
		GM_xmlhttpRequest({
			method: 'GET',
			url: url,
			onload: function (response) {
				var rs = response.responseText;
				
				var r, m, full = [], c = 0;
				
				// full
				// "iurl":"
				r = /"iurl":"([^"]+)/g;
				if (r.exec(rs)) {
					r.lastIndex = 0;
					while (m = r.exec(rs)) {
						full[c] = m[1].replace(/\\\//g, '/');
						c++;
					}
				}
				
				var r, m, c = 0;
				// thumb
				r = /><img src='http:\/\/ts([^']+)/g;
				if (r.exec(rs)) {
					r.lastIndex = 0;
					while (m = r.exec(rs)) {
						if (c >= 4) break;
						
						f = (full[c]) ? full[c] : '';
						d1b.innerHTML += '<img src="http://ts'+m[1]+'" id="'+f+'" class="exe-yahoo" style="border:1px solid lime;height:160px;">';
						c++;
					}
					
					sam_molyneux_journals_update();
				} else
					d1b.innerHTML = '0';
			}
		});
	}
	function sam_molyneux_researcher_images() {
		
		// small & large
		// https://www.google.com/search?q='++'&aq=f&um=1&ie=UTF-8&hl=en&tbm=isch
		
		d1.innerHTML = '';
		
		// Reset
		d1.style.backgroundColor = '#eee';
		
		//~ d1b.innerHTML = '';
		
		D1_HIDDEN = '';
		
		// yahoo
		//sam_molyneux_journals_yahoo();
		
		// google 2
		//~ var d;
		//~ d = document.createElement('div');
		//~ d.setAttribute('id','d1a2');
		//~ d.innerHTML = '&nbsp;';
		//~ d1.appendChild(d);
		//~ d1a2 = document.getElementById('d1a2');
		//~ d1a2.style.width='100%';
		
		// !??
		//var u = 'https://www.google.com/search?q='+encodeURIComponent(di.value)+'&aq=f&um=1&ie=UTF-8&hl=en&tbm=isch&num=10&biw=&bih=&sei=&'+Math.random()*1000;
		//var u = 'https://www.google.com/search?biw=1152&bih=720&tbm=isch&sa=1&q='+encodeURIComponent(di.value)+'&oq='+encodeURIComponent(di.value)+'&gs_l=';
		//console.log(u);
		var u = 'https://www.google.com/search?q='+encodeURIComponent(di.value.replace(/&/g, 'and'))+'&aq=f&um=1&ie=UTF-8&hl=en&tbm=isch&num=10&biw=&bih=&sei=&'+Math.random()*1000;
		// !! encode (&) breaks
		
		// google
		GM_xmlhttpRequest({
			method: 'GET',
			url: u,
			onload: function (response) {
				var rs = response.responseText;
				
				if (response.status != 200) {
					d1.style.backgroundColor = 'pink';
					window.open(u, 'new');
					return;
				}
				
				//<div class="rg_meta">
				var r, m, meta, img, div, el_img, count = 0;
				r = /<!--m-->((.|\s)*?(?=<!--n-->|$)|$)/g;
				while (m = r.exec(rs)) {
					
					if (count >= 14) break;
					
					// Link
					// ex http://www.sdu.dk/om_sdu/.../forskningsleder
					var link = /<a href="http:\/\/www\.google\.com\/imgres\?imgurl=[^&]+&amp;imgrefurl=([^&]+)/.exec(m[1]);
					if (link) {
						link = decodeURIComponent(decodeURIComponent(link[1]));
					} else
						link = false;
					
					// Meta
					// .pt = filename (OR extended description?)
					// .s = description
					// .os = file size, either "4KB" or "1.4MB"
					// .tu = Google thumbnail image full URL
					// .fn = filename (e.g. file.jpg)
					meta = /<div class="rg_meta">((.|\s)*?(?=<\/div>|$)|$)/.exec(m[1]);
					if (meta) {
						meta = __js_clean_html_str(meta[1]).trim();
						meta = JSON.parse(meta);
						meta.pt = (meta.pt) ? meta.pt : '';
						meta.s  = (meta.s)  ? meta.s  : '';
						meta.fn  = (meta.fn)  ? meta.fn  : '';
						meta.os  = (meta.os.indexOf('MB') != -1)  ? meta.os.replace(/[^\d]/g, '')*1000 : meta.os.replace(/[^\d]/g, '')*1;
					} else {
						meta = {
							pt: '',
							s: ''
						};
					}
					console.log(meta);
					
					
					//http://www.chw.org/~/media/Images/Modules/Physician%2520Directory/Physicians/F/Jordan%2520N%2520Fink.jpg%3Fmw%3D292
					//http://www.chw.org/~/media/Images/Modules/Physician%2520Directory/Physicians/F/Jordan%2520N%2520Fink.jpg%3Fmw%3D292
					//http://www.chw.org/~/media/Images/Modules/Physician%20Directory/Physicians/F/Jordan%20N%20Fink.jpg?mw=292
					//http://www.chw.org/~/media/Images/Modules/Physician%2520Directory/Physicians/F/Jordan%2520N%2520Fink.jpg%3Fmw%3D292
					//~ img = /<a class="rg_l" href="http:\/\/www\.google\.com\/imgres\?imgurl=([^&"]+)/.exec(m[1]);
					img = /<a href="http:\/\/www\.google\.com\/imgres\?imgurl=([^&"]+)/.exec(m[1]);
					if (img) {
						img = img[1].trim();
						img = decodeURIComponent(decodeURIComponent(img));
						//img = __js_clean_html_str(img);
					} else
						img = '';
					
					//~ console.log(img);
					
					// Get the domain of full img URL
					meta.domain__ = img.parseURL().host.replace(/^www\./, '');
					
					
					div = document.createElement('div');
					div.setAttribute('style', 'border:1px solid #a2a2a2;border-collapse:collapse;float:left;width:200px;height:300px;overflow:auto;cursor:pointer;');
					
					el_img = document.createElement('img');
					el_img.setAttribute('style', 'max-width:180px;max-height:120px;');
					el_img.src = (meta.os > 600) ? meta.tu : img;
					el_img.submit_src = img;
					el_img.onclick = sam_molyneux_researcher_images__imgClick;
					
					div.appendChild(el_img);
					div.appendChild(document.createElement('br'));
					//~ div.appendChild(document.createTextNode(meta.os));	//DEBUG .os
					//~ div.appendChild(document.createElement('br'));		//DEBUG .os
					
					// o.bold_array_name
					// o.bold_array_company
					
					// Title
					var bold_init = MT__bold(
								meta.s,
								o.bold_array_name
							);
					div.appendChild(
						MT__bold(
								bold_init,
								o.bold_array_company,
								{
									color: 'blue',
									return_div_element: true // !
								}
							)
							.div_element
					);
					
					// Desc.
					var bold_init = MT__bold(
								meta.pt,
								o.bold_array_name
							);
					var d =
						MT__bold(
								bold_init,
								o.bold_array_company,
								{
									color: 'blue',
									return_div_element: true // !
								}
							)
							.div_element;
					d.setAttribute('style', 'border-top:1px dashed #a2a2a2;width:100%;');
					div.appendChild(
						d
					);
					
					// fn
					var bold_init = MT__bold(
								meta.fn,
								o.bold_array_name
							);
					var d =
						MT__bold(
								bold_init,
								o.bold_array_company,
								{
									color: 'blue',
									return_div_element: true // !
								}
							)
							.div_element;
					d.setAttribute('style', 'border-top:1px dashed #a2a2a2;width:100%;');
					div.appendChild(
						d
					);
					
					// Domain
					var bold_init = MT__bold(
								meta.domain__,
								o.bold_array_name
							);
					var d =
						MT__bold(
								bold_init,
								o.bold_array_company,
								{
									color: 'blue',
									return_div_element: true // !
								}
							)
							.div_element;
					d.setAttribute('style', 'border-top:1px dashed #a2a2a2;width:100%;');
					div.appendChild(
						d
					);
					
					// Link
					if (link) {
						var a = document.createElement('a');
						a.href = link;
						a.innerText = 'link';
						a.onclick = function() {
							window.open(this.href, 'new');
							return false;
						}
						div.appendChild(a);
					}
					
					// ...
					d1.appendChild(div);
					count++;
				}
				
				// add
				if (count > 0) {
					var div = document.createElement('div');
					div.setAttribute('style', 'height:1200px;');
					d1.appendChild(div);
				}
				
				return;
			}
		});
	}
	function sam_molyneux_researcher_images__imgClick() {
		
		// GO TO NEXT TAB!
		this.style.border = '4px solid LightGreen';
		
		new AMT___core_factory().nextTab();
			
		var u, v, w;
		u = encodeURIComponent(code);
		v = encodeURIComponent(this.submit_src); // Full size URL
		//~ v = encodeURIComponent(this.src); // Full size URL
		// THUMBNAIL SRC // v = encodeURIComponent(this.src);
		w = encodeURIComponent(title);
		
		//~ el.id = x;
		
		var orig = this;
		
		// upload image
		GM_xmlhttpRequest({
			method: "GET",

			url: MT___host+'/mturk/Sam_Molyneux/Sam_Molyneux.php?u='+u+'&v='+v+'&w='+w,

			onload: function (response) {
				var rs = response.responseText;
				console.log(rs);
				if (rs == '1') {
					// orig
					orig.style.border = '12px solid LightGreen';
					//
					doSubmit();
				} else
					orig.style.border = '6px solid #3a3c3a';
			}
		});
	}
	function sam_molyneux_researcher_images__update() {

		// 1 post .exe
		var x = document.getElementsByClassName('exe');
		for (var i in x) {
			x[i].onclick = function() {
				this.style.border = '4px solid LightGreen';
				
				var u;
				u = 'u='+encodeURIComponent(code);
				u+= '&v='+encodeURIComponent(this.src);
				u+= '&w='+encodeURIComponent(title);
				
				var orig = this;
				
				// upload image
				GM_xmlhttpRequest({
					method: "POST",
					url: MT___host+'/mturk/Sam_Molyneux/Sam_Molyneux.php',
					data: u,
					headers: {
						"Content-Type": "application/x-www-form-urlencoded"
					},
					onload: function (response) {
						var rs = response.responseText;
						console.log(rs);
						
						if (rs == '1') {
							// orig
							orig.style.border = '12px solid LightGreen';
							//
							doSubmit();
						} else
							orig.style.border = '6px solid #3a3c3a';
					}
				});
			}
		}
		
		// 2 get .exe-yahoo
		var x = document.getElementsByClassName('exe-yahoo');
		for (var i in x) {
			x[i].onclick = function() {//console.log('2');
				this.style.border = '4px solid LightGreen';
				
				var x;
				// Change src if diff.
				if (this.src != this.id) {
					x = this.src;
					this.src = this.id;
				}
				
				var u, v, w;
				u = encodeURIComponent(code);
				v = encodeURIComponent(this.id); // Full size URL
				// THUMBNAIL SRC // v = encodeURIComponent(this.src);
				w = encodeURIComponent(title);
				
				this.id = x;
				
				var orig = this;
				
				// upload image
				GM_xmlhttpRequest({
					method: "GET",
		
					url: MT___host+'/mturk/Sam_Molyneux/Sam_Molyneux.php?u='+u+'&v='+v+'&w='+w,
		
					onload: function (response) {
						var rs = response.responseText;
						console.log(rs);
						if (rs == '1') {
							// orig
							orig.style.border = '12px solid LightGreen';
							//
							doSubmit();
						} else
							orig.style.border = '6px solid #3a3c3a';
					}
				});
			}
		}
	}
