		function Naomi_Bardach_yelp(u) {
			if (!/http:\/\/(www\.|)yelp\.com\/biz\/[^\/]+$/i.exec(u)) return;
			u = u + '?sort_by=date_desc';
			GM_xmlhttpRequest({
				method: 'GET',
				url: u,
				onload: function (response) {
					var rs=response.responseText;
					
					if (response.status != 200) return;
					
					var r;
					r = /<li id="review_((.|\s)*?(?=[\r\n]+	<\/li>|$)|$)/g;
					
					var sbm = true;
					if (r.exec(rs)) {
						var m;
						r.lastIndex = 0;
						var r2, r3;
						var i = 0;
						var i2= 0;
						var num_rv = /<span itemprop="reviewCount">([\d,]+)<\/span> review/.exec(rs);
						if (!num_rv) {
							sbm = false;
							console.log('nrv');
						} else {
							num_rv = num_rv[1].replace(/,/g, '');
						}
						while (m = r.exec(rs)) {
							
							r2 = /<meta itemprop="datePublished" content="([\d\-]+)"/.exec(m[1]);
							if (r2) {
								r2 = r2[1];
								r3 = /^(\d{4})-(\d{2})-(\d{2})$/.exec(r2);
								if (!r3) sbm = false;
								else {
									r3[2] = r3[2].replace(/^0(\d)$/, '$1');
									r3[3] = r3[3].replace(/^0(\d)$/, '$1');
									q[i].value = r3[2]+'/'+r3[3]+'/'+r3[1];
								}
							} else sbm = false;
							
							r2 = /<meta itemprop="ratingValue" content="([\d\.]+)"/.exec(m[1]);
							if (r2) {
								q[i+1].value = r2[1];
							} else sbm = false;
							
							r2 = /<p class="review_comment" itemprop="description">([^\r\n]+)/.exec(m[1]);
							if (r2) {
								r2 = r2[1];
								r2 = r2.replace(/<br>/g, "\n");
								r2 = r2.replace(/<\/p>/g, "");
								if (/[<>]/.exec(r2)) {
									sbm = false;
									console.log(r2);
								} else {
									r2 = __js_clean_html_str(r2).trim();
									q2[i2].value = r2;
									//q[i+2].value = r2;
									if (r2 == '') sbm = false;
								}
							} else sbm = false;
							
							i+=2;//3
							i2++;
							if (i2 == 4) break; // ONLY 4!
						} //
						console.log(i);
						//
						if (i < 8) {
							while (i < 8) {
								//if (q[i])
									q[i].value   = '0';
									q[i+1].value = '0';
								//if (q[i])
									q2[i2].value = '0';
								i+=2;
								i2++;
							}
						}
						if (i2 != num_rv && i2 != 4) { // if not equal && != 4
							console.log('diff ' +i2+ ' ' +num_rv);
							sbm = false;
						}
						console.log(sbm);
						if (sbm) {
							console.log(doSubmit);
							doSubmit();
						}
					} else if (
						rs.indexOf('<h2 id="total_reviews">') == -1 &&
						rs.indexOf('<span itemprop="reviewCount">') == -1 &&
						rs.indexOf('"hasReviews": false') != -1
						)
					{
						for (var i in q) {
							if (i == 'length') break;
							q[i].value = '0';
						}
						for (var i in q2) {
							if (i == 'length') break;
							q2[i].value = '0';
						}
						//
						doSubmit();
					}
				}
			});
		}
