		function ai_wo_URL_scrapeLinkedin(inp) {
			GM_xmlhttpRequest({
				method: 'GET',
				url: inp.value,
				onload: function (response) {
					var rs=response.responseText;
					
					var r;
					
					r = /<h1 class="name">[\r\n\t\s]+<a href="(\/company\/[^\?]+)\?trk=company_name">/.exec(rs);
					
					if (!r)
						inp.style.backgroundColor = 'white';
					else {
						r = r[1];
						r = 'http://www.linkedin.com' + __js_clean_html_str(r);
						document.getElementById('Q1Url').value = r;
						document.getElementById('Q1Url').focus();
						if  (
							!/https?:\/\/\w+\.linkedin\.com\/company\/\d+$/.exec(r) &&
							/https?:\/\/\w+\.linkedin\.com\/company\/[^\/]+$/.exec(r)
							)
							doSubmit();
					}
				}
			});
		}
