		function Bongarde_Media_Find_Website_Address_load_skips() {
			GM_xmlhttpRequest({
				method: 'GET',
				url: MT___host+'/mturk/util.php?austin_load_skips=',
				onload: function (response) {
					var rs=response.responseText;
					SKIP_SITES = rs.split("\n");
					
					// SUBDOMAINS!
					var x;
					for (var i in SKIP_SITES) {
						if (x = /\.([^\.]+\.[^\.]+)$/.exec(SKIP_SITES[i])) {
							SKIP_SITES[i] = x[1];
						}
					}
					//~ Brittany_Graham_Find_Website_Address(d1, d3.value);
					//~ if (b2 != '')
						//~ Brittany_Graham_Find_Website_Address(d1b, d3b.value, false);
					
					Bongarde_Media_Find_Website_Address__yahoo_init(d1,  d3 );
					Bongarde_Media_Find_Website_Address__yahoo_init(d1b, d3b);
					Bongarde_Media_Find_Website_Address__yahoo_init(d1c, d3c);
					
					//~ Bongarde_Media_Find_Website_Address(d1,  d3.value );
					//~ TOTAL_CALLS++;
					//~ Bongarde_Media_Find_Website_Address(d1b, d3b.value);
					//~ TOTAL_CALLS++;
					//~ Bongarde_Media_Find_Website_Address(d1c, d3c.value);
					//~ TOTAL_CALLS++;
				}
			});
		}
