		// ...
		function Bongarde_Media_Find_Website_Address(return_object) {
			
			//~ console.log(return_object);
			var div	= return_object.obj_vars.div;
			var rs	= return_object.rs;
			
			// 0=url
			// 1=full
			//console.log(rs);
			//~ if (rs.length) {
				//~ if (d1c.src == '')
					//~ d1c.src = rs[0][0]; // feeling lucky
			//~ } else {
				//~ d1c.style.border = '10px solid blue';
				//document.body.style.backgroundColor = 'blue';
			//~ }
			
			if (!rs.length) {
				div.innerHTML = '<b>0</b>';
				return;
			}
			
			var count = 0;
			var x, match, out;
			var r, m;
			var fb = '';
			var domain;
			var short_domain;
			var y;
			
			for (var i in rs) {
				
				//~ var d = document.createElement('div');
				//~ d.setAttribute('style', 'border-bottom:1px solid #a2a2a2;cursor:pointer;');
				//~ d.className = 'divs-yahoo';
				//~ d.y_url = rs[i][0];
				//~ d.onclick = function() {
					//~ this.style.backgroundColor = 'LightGreen';
					//~ d1c.src = this.y_url;
					//~ d1c.scrollIntoView();
				//~ }
				//~ d.innerHTML = rs[i][0] + '<br>' + rs[i][1];
				//~ d1b.appendChild(d);
				
				
				
				// add bold to result
				// b2, b3, b4
				var bold_array;
				switch(div.id) {
					case 'd1':
						bold_array = (b1).split(' ');
						break;
					case 'd1b':
						bold_array = (b1).split(' ');
						break;
					case 'd1c':
						bold_array = (b1).split(' ');
						break;
				}
				
				var x = rs[i][0];
				
				// trailing
				x = x.replace(/(\w+)\/[^$]*$/, '$1'); //trailing 0, & slash
				
				// regular = ^http://www.site.com$
				// subdomains = [\.\/]site.com$
				if (y = /\.([^\.]+\.[^\.]+)$/.exec(x)) {
					short_domain = y[1];
				} else
					short_domain = x;
				
				if (__js_inarray(SKIP_SITES, short_domain)) {//border-top:1px solid #3a4d3a;border-bottom:1px solid #3a4d3a;
					div.innerHTML += '\
						x'+x+'\
						<br>';
					continue;
				}
				else
					FOUND_ONE_NONSKIP = true; // FOUND_ONE_NONSKIP
				
				
				// add bold (bold_array)
				rs[i][1] = MT__bold(rs[i][1], bold_array);
				
				// classname is http://(www. = '')x.com (no www)
				var cls = x.replace(/^(https?:\/\/)www\./, '$1');
				
				div.innerHTML += '\
					<p class="class_'+cls+'">\
						<textarea type="button" class="exe" style="width:100%;zoom:0.8;cursor:pointer;padding:0;margin:0;" readOnly>'+x+'</textarea>\
						<a href="'+rs[i][0]+'" target="_blank">link</a> \
						<a href="'+rs[i][0]+'" target="d2">ifr</a> \
						<input type="button" value=" S " id="'+x+'" class="exe-skip" style="width:auto;" > \
						<br >'+rs[i][1]+'\
					</p>';
				
				// push first match
				// but only if array is empty
				// or all in array equal this domain
				// DO THIS AFTER BUTTONS ARE ON PAGE!
				if (count == 0) {
					if (ARRAY_FIRST_FINDS.length > 0 && ARRAY_FIRST_FINDS[0] == x) {
						ARRAY_FIRST_FINDS.push(x);
					} else if (ARRAY_FIRST_FINDS.length == 0)
						ARRAY_FIRST_FINDS.push(x);
				}
				
				count++;
			}
				
			if (count > 0) {
				div.innerHTML += '<div style="height:1200px;">&nbsp;</div>';
			}
			
			var x = document.getElementsByClassName('exe');
			for (var i in x) {
				x[i].onclick = function() {
					this.style.backgroundColor = 'LightGreen';
					document.getElementById('Website').value = this.value;
					doSubmit();
				}
			}
			var x = document.getElementsByClassName('exe-skip');
			for (var i in x) {
				x[i].onclick = function() {
					this.style.backgroundColor = 'LightGreen';
					var btn = this;
					GM_xmlhttpRequest({
						method: 'GET',
						url: MT___host+'/mturk/util.php?austin_load_skips='+encodeURIComponent(this.id),
						onload: function (response) {
							var rs=response.responseText;
							btn.value = ' ---X--- ';
							SKIP_SITES.push(btn.id);
						}
					});
				}
			}
			// p
			var x = div.getElementsByTagName('p');
			for (var i in x) {
				if (i == 'length') break;
				//mouseover
				x[i].addEventListener('mouseover', function() {
					var x = document.getElementsByTagName('p');
					for (var i in x) {
						if (i == 'length') break;
						if (x[i].className == this.className) {
							x[i].style.backgroundColor = 'LightGreen';
						} else {
							x[i].style.backgroundColor = '';
						}
					}
					//this.style.backgroundColor = 'LightGreen';
					// Could do this also! .getElementsByClassName('class_');
				}, false);
				//mouseout
				x[i].addEventListener('mouseout', function() {
					var x = document.getElementsByTagName('p');
					for (var i in x) {
						if (i == 'length') break;
						if (x[i].className == this.className) {
							x[i].style.backgroundColor = '';
						}
					}
					//this.style.backgroundColor = 'LightGreen';
					// Could do this also! .getElementsByClassName('class_');
				}, false);
			}
		}
