					var txa = document.createElement('textarea');
					txa.setAttribute('style','width:100%;zoom:1;cursor:pointer;padding:0;margin:0;resize:none;'); //resize:none;
					txa.readOnly = true;
					txa.value = x;
					txa.parent_div = out_div;
					txa.parent_txa = out_div.txa
					d.appendChild(txa);
