					//~ x = x.replace(/(\w+)\/[^$]*$/, '$1'); //trailing 0, & slash
					
					// http
					//~ x = x.replace(/^https?:\/\//, ''); // beginning
					
					//~ // regular = ^http://www.site.com$
					//~ // subdomains = [\.\/]site.com$
					//~ if (y = /\.([^\.]+\.[^\.]+)$/.exec(x)) {
						//~ short_domain = y[1];
					//~ } else
						//~ short_domain = x;
					
