		var SKIP_SITES;
		function Andrew_Mauboussin_Find_Website_Address_load_skips() {
			GM_xmlhttpRequest({
				method: 'GET',
				url: MT___host+'/mturk/util.php?austin_load_skips=',
				onload: function (response) {
					var rs=response.responseText;
					
					//~ SKIP_SITES = rs.split("\n");
					
					var x = rs.split("\n");
					
					SKIP_SITES = {}; // ASSOC.
					
					// full
					for (var i in x) {
						SKIP_SITES[x[i]] = true;
					}
					
					// SUBDOMAINS!
					// .xxx.[^.]+$
					// 
					for (var i in x) {
						var y;
						if (y = /\.([^\.]{3,}\.[^\.]+)$/.exec(x[i])) {
							SKIP_SITES[y[1]] = true;
						}
					}
					
					Andrew_Mauboussin_Find_Website_Address__SP_init();
			
				}
			});
		}
