		function EAT_Club_find_comp_email(rs, out_div) {
			
			// make yahoo results row
			EAT_Club_find_comp_email__yahoo_rows(rs, out_div);
			
			if (rs.length > 0) {
				var el = document.createElement('div');
				el.setAttribute('style','height:1200px;');
				out_div.appendChild(el);
			} else {
				out_div.innerText = '0';
			}
			
			// Post processing for Scrape
			// Are the first links on left and right the same domain? > .accept, .scrape
			// Is top link on right in the results of left? > .scrape
			// out_div.load_stats
			// out_div.load_stats.good_domains[short_domain 1, 2, 3]
			
			// Unique domains only.
			// button.prototype.do_scrapy ()
			//   .status of scrape
			//   .able to check how many are running and how many are complete
			
			// SET first_run TO TRUE!
			out_div.load_stats.first_run_complete = true;
			
			// Are both divs complete?
			if  (
				d1.load_stats. first_run_complete &&
				d1b.load_stats.first_run_complete
				)
			{
				// click the left + right first 20
				// thenceforward click all the 4 searches
				var clicked_domains = [];
				var first = d1 .getElementsByTagName('input');
				var first20_clicked = false;
				for (var i in first) {
					if (first[i].arg_max_pages_to_fetch == NUM_SEARCH_LARGE) {
						clicked_domains.push(first[i].short_domain);
						first[i].click();
						break;
					}
				}
				var first = d1b.getElementsByTagName('input');
				var first20_clicked = false;
				for (var i in first) {
					if (first[i].arg_max_pages_to_fetch == NUM_SEARCH_LARGE) {
						if (!__js_inarray(clicked_domains, first[i].short_domain)) {
							clicked_domains.push(first[i].short_domain);
							first[i].click();
						}
						break;
					}
				}
				// rest (4s)!
				var x = document.getElementsByTagName('input');
				for (var i in x) {
					if (i == 'length') break;
					if (x[i].className.indexOf('class__scrapyURL__4_') == 0) {
						if (!__js_inarray(clicked_domains, x[i].short_domain)) {
							clicked_domains.push(x[i].short_domain);
							x[i].click();
						}
					}
				}
			}
		}
		
		/*
		 * EAT_Club_find_comp_email__yahoo_rows()
		 */
		function EAT_Club_find_comp_email__yahoo_rows(rs, out_div) {
			
			var qualified_url;
			var short_domain;
			var full_url;
			var x;
			var y;
			var first_run = false;
			
			for (var i in rs) {
				
				if (i > 2) // ONLY 4!!
					break;
				
				full_url = rs[i][0];
				
				x = full_url;
				x = x.replace(/(\w+)\/[^$]*$/, '$1'); //trailing 0, & slash
				qualified_url = x;
				
				// regular = ^http://www.site.com$
				// subdomains = [\.\/]site.com$
				if (y = /[\.\/]([^\.\/]{4,}\.[^\.]+)$/.exec(qualified_url)) {
					short_domain = y[1];
				} else
					short_domain = qualified_url;
				short_domain = short_domain.replace(/^https?:\/\/(www\.|)/i, '');
				
				if (__js_inarray(SKIP_SITES, short_domain)) {
					var el = document.createElement('p');
					el.innerText = 'x' + qualified_url;
					out_div.appendChild(el);
					continue;
				}
				
				// load stats!
				//first_run: false
				//first_good_domain_found: ''
				if (!out_div.load_stats.first_run_complete && !first_run) {
					out_div.load_stats.first_good_domain_found = short_domain;
					first_run = true; // this only happens on first run //
				}
				// push to div. good domains
				out_div.load_stats.good_domains.push(short_domain);
				
				// output
				var el_div = document.createElement('div');
				el_div.setAttribute('style','cursor:pointer;');
				el_div.setAttribute('class','class__highlightURL__'+short_domain); // "short_domain" rather than "x"
				el_div.isClicked = false;
				//click
				el_div.addEventListener('click', function(e) {
					this.getElementsByTagName('input')[0].click();
					this.isClicked = true;
					// .isClicked others
					var x = document.getElementsByTagName('div');
					for (var j in x) {
						if (j == 'length') break;
						if (x[j].className == this.className) {
							x[j].isClicked = true;
							// // // //x[j].style.backgroundColor = 'LightGreen';
						} else {
							x[j].isClicked = false; // unclick ?
						}
					}
					e.preventDefault();
					e.stopPropagation();
					return false;
				}, false);
				//mouseover
				el_div.addEventListener('mouseover', function() {
					var x = document.getElementsByTagName('div');
					for (var j in x) {
						if (j == 'length') break;
						if (x[j].className == this.className) {
							x[j].style.backgroundColor = 'LightGreen';
						} else if (!x[j].isClicked) {
							// // // //x[j].style.backgroundColor = '#eee';
						}
					}
				}, false);
				//mouseout
				el_div.addEventListener('mouseout', function() {
					var x = document.getElementsByTagName('div');
					for (var j in x) {
						if (j == 'length') break;
						if (x[j].className == this.className) { // && !x[j].isClicked
							x[j].style.backgroundColor = '#eee';
						}
					}
				}, false);
				
				// regular "search"-type button
				var el_inp = document.createElement('input');
				el_inp.setAttribute('style','width:auto;');
				el_inp.setAttribute('type','button');
				el_inp.value = rs[i][0]; // "qualified_url" would be short
				el_div.appendChild(el_inp);
				
				// link
				var el_a = document.createElement('a');
				el_a.setAttribute('style','width:auto;margin:0 2px 0 2px;');
				el_a.setAttribute('type','button');
				el_a.innerText = 'link';
				el_a.target = '_blank';
				el_a.href = rs[i][0]; // full href!
				//~ el_inp.onclick = function() {
					//~ 
				//~ }
				el_div.appendChild(el_a);
				
				
				// SKIP BUTTON CREATE
				var el_inp_skip = new AMT___items_factory();
				el_div.appendChild(
					// (url, skips_key_php_get, callback)
					el_inp_skip.create__input_skip_button(
						qualified_url,
						'austin_load_skips',
						function(skip_btn_id) {
							SKIP_SITES.push(skip_btn_id); // ADD SKIP SITE HERE!
						}
					)
				);
				el_div.appendChild(document.createElement('br'));
				
				// scrapers
				// 4
				var el_inp_scrapy = new AMT___items_factory();
				el_div.appendChild(
					// 
					el_inp_scrapy.create__input_scrapy_button(
						short_domain,
						full_url,
						// options
						EAT_Club_find_comp_email__scrape_btn_options(4, short_domain), //, start_urls
						// callback
						EAT_Club_find_comp_email__scrapy_process_response //, // arg= scrapy_jobid, array_json_list, seed_object
					)
				);
				// 20
				var el_inp_scrapy = new AMT___items_factory();
				el_div.appendChild(
					// 
					el_inp_scrapy.create__input_scrapy_button(
						short_domain,
						full_url,
						// options
						EAT_Club_find_comp_email__scrape_btn_options(NUM_SEARCH_LARGE, short_domain), 
						// callback
						EAT_Club_find_comp_email__scrapy_process_response //, // arg= scrapy_jobid, array_json_list, seed_object
					)
				);
				el_div.appendChild(document.createElement('br'));
				
				// YAHOO TEXT RESULT !!!
				var el_p = document.createElement('p');
				el_p.innerHTML = rs[i][1];
				el_div.appendChild(el_p);
				
				// container
				out_div.appendChild(el_div);
			}
		}
		// scrapy_jobid
		// array_json_list
		// seed_object
		
		// NAME_ARRAY
		// !! Scrape the contexts for name matching !!
		
		// results_array[]
		// [{r1}, {r2}, ... {r N}]
		/*
		{
		email_email: 'str email',
		email_contexts: ['str context 1','str context 2', ... 'str context N'],
		url: 'str url'
		}
		
		** add email_contexts_contains_name: (Boolean)
		
		*/
		function EAT_Club_find_comp_email__scrapy_process_response(scrapy_jobid, scrapy_results_object, seed_object) {
			
			// set scrapy result array of this
			var x = document.getElementsByClassName(seed_object.btn_className);
			for (var i in x) {
				if (i == 'length') break;
				//x[i].scrapy__array_json_list = array_json_list.matches;
				x[i].scrapy_results_object = scrapy_results_object;
			}
			
			// IS THERE A NAME MATCH IN RESULTS?
			var tmp_contains_match = false;
			if (NAME_ARRAY.length) {
				top_loop:
				for (var j in scrapy_results_object.matches) {
					var rslt = scrapy_results_object.matches[j];
					//console.log(rslt);
					for (var k in rslt.email_contexts) {
						var context = rslt.email_contexts[k].toLowerCase();
						for (var l in NAME_ARRAY) {
							if (context.indexOf(NAME_ARRAY[l]) != -1) {
								rslt.email_contexts_contains_name = true; // set email_contexts_contains_name !!
								tmp_contains_match = true;
								//break top_loop; //?
							}
						}
					}
				}
			}
			
			// Display results amounts?
			if (scrapy_results_object.matches.length == 0) {
			
			//if (scrapy_results_object.length == 0 || scrapy_results_object[0] == '') {
				var x = document.getElementsByClassName(seed_object.btn_className);
				for (var i in x) {
					if (i == 'length') break;
					// update values
					x[i].value += '*0*';
					// styles
					x[i].style.border = '';
					x[i].style.backgroundColor = 'teal';
					// onclick
					x[i].onclick = function() {
					}
				}
			} else {
				var x = document.getElementsByClassName(seed_object.btn_className);
				for (var i in x) {
					if (i == 'length') break;
					// update values
					x[i].value += '*' +scrapy_results_object.matches.length+ '*';
					// styles
					x[i].style.border = '6px solid #a2a2a2';
					// onclick
					x[i].onclick = function() {
						EAT_Club_find_comp_email__scraper_display_result(this, this.scrapy_results_object); //btn, array
					}
					
					// contains match !?
					if (tmp_contains_match) {
						x[i].style.zoom = 2;
						x[i].click();
					}
				}
			}
		}
		// results_array[]
		// [{r1}, {r2}, ... {r N}]
		/*
		{
		email_email: 'str email',
		email_contexts: ['str context 1','str context 2', ... 'str context N'],
		url: 'str url'
		}
		 
		result . email_contexts_contains_name: (Boolean)
		*/
		function EAT_Club_find_comp_email__scraper_display_result(btn, scrapy_results_object) {
			
			var out_div = d2;
			
			out_div.innerHTML = '';
			
			console.log(btn);
			console.log(scrapy_results_object);
			
			// scrollIntoView()?
			
			var el_select = document.createElement('select');
			out_div.appendChild(el_select);
			
			el_select.setAttribute('style','display:inline;width:98%;height:140px;');
			el_select.multiple = 'multiple';
			for (var i in scrapy_results_object.matches) {
				
				rslt = scrapy_results_object.matches[i];
				
				// add option
				el_option = document.createElement('option');
				el_option.value = rslt.email_email;
				el_option.innerText = rslt.email_email;
				// add email_contexts_contains_name !!
				if (rslt.email_contexts_contains_name) {
					el_option.setAttribute('style', 'background-color:LightGreen;color:blue;');
				}
				el_option.matches = rslt;
				el_select.appendChild(el_option);
			}
			el_select.onchange = function() {
				EAT_Club_find_comp_email__scraper_display_result__selectChange(
					this.options[this.selectedIndex].matches // ?
				);
			}
			for (var i = 0; i<20; i++) {// append blank lines!
				// add option
				el_option = document.createElement('option');
				el_option.value = '';
				el_option.innerText = '';
				el_select.appendChild(el_option);
			}
			
			// urls select
			var el_select2 = document.createElement('select');
			out_div.appendChild(el_select2);
			el_select2.setAttribute('style','display:inline;width:98%;height:140px;');
			el_select2.multiple = 'multiple';
			el_select2.onclick = function() {
				if (this.value == '') return;
				window.open(this.value,'new');
			}
			// urls
			console.log(scrapy_results_object.urls.complete_high_to_low);
			for (var i in scrapy_results_object.urls.complete_high_to_low) {
				
				rslt = scrapy_results_object.urls.complete_high_to_low[i]; // {.url, .priority}
				
				// add option
				el_option = document.createElement('option');
				el_option.value = rslt.url;
				el_option.innerText = rslt.url;
				// color
				var bg;
				switch(rslt.priority) {
					case 'high':
						bg = 'LightGreen';
						break;
					case 'low':
						bg = 'Orange';
						break;
					case 'none':
						bg = '#fff';
						break;
					case 'outside':
						bg = 'pink';
						break;
				}
				el_option.setAttribute('style', 'background-color:'+bg+';');
				el_select2.appendChild(el_option);
			}
			for (var i = 0; i<20; i++) {// append blank lines!
				// add option
				el_option = document.createElement('option');
				el_option.value = '';
				el_option.innerText = '';
				el_select2.appendChild(el_option);
			}
			
			// br
			out_div.appendChild(document.createElement('br'));
			
			// auto-click first email
			if (scrapy_results_object.matches.length > 0) {
				EAT_Club_find_comp_email__scraper_display_result__selectChange(
					el_select.options[0].matches
				);
			}
			
			out_div.appendChild(document.createElement('br'));
		}
		function EAT_Club_find_comp_email__scraper_display_result__selectChange(results_array) {
			
			var out_div = d2;
			
			var old_divs = out_div.getElementsByTagName('div');
			for (var i = old_divs.length - 1; i>=0; i--) {
				old_divs[i].parentNode.removeChild(old_divs[i]);
			}
			
			var email_contexts = results_array.email_contexts;
			var url = results_array.url;
			
			var el_div = document.createElement('div');
			el_div.setAttribute('style','width:100%;height:40px;overflow:hidden;border:1px solid #a2a2a2;');
			//el_div.innerText = url;
			
			var el_a = document.createElement('a');
			el_a.href = url;
			el_a.target = '_blank';
			el_a.innerText = url;
			el_div.appendChild(el_a);

			out_div.appendChild(el_div);
			
			for (var j in email_contexts) {
				var context = email_contexts[j]	.replace(/<[^>]*>/g, ' ').replace(/[<>]/g, ' ');
				context = __js_clean_html_str(context);
				context = context				.replace(/<[^>]*>/g, ' ').replace(/[<>]/g, ' ');
				context = context.trim();
				context = context.replace(/[\t\s]*[\r\n]+[\t\s]*/g, '<br>');
				context = context.replace(/\t/g, '&nbsp;&nbsp;');
				context = context.replace(/\s{2,}/g, '&nbsp;&nbsp;');
				context = context.replace(
					new RegExp('(' + __js_escape_regEx(results_array.email_email) + ')', 'gi'),
					'<span style="zoom:1.2;color:DarkGreen;">$1</span>'
				);
				context = MT__bold(context, NAME_ARRAY);
				
				var el_div = document.createElement('div');
				el_div.setAttribute('style','cursor:pointer;width:98%;height:auto;overflow:auto;border-bottom:3px dashed #a2a2a2;');
				el_div.innerHTML = context;
				el_div.email = results_array.email_email;
				el_div.onclick = function() {
					this.style.backgroundColor = 'LightGreen';
					document.getElementById('Q1Url').value = this.email;
					if (this.email.length > 6 && this.email.indexOf('@') != -1) {
						doSubmit();
					}
				}
				out_div.appendChild(el_div);
			}
		}
