		function Devon_George_li_prof(u, getProfileCompanies) {
			
			GM_xmlhttpRequest({
				method: "GET",
				url: u,
				onload: function(response) {
					var rs = response.responseText;
					
					if (response.status != 200) {
						out.innerHTML = response.status;
						return;
					}
					
					if (getProfileCompanies) {
						scout_analytics_parseProfileLI(rs, true);//short_search = true
						return;
					}
					
					// dashes
					rs = rs.replace(/\\u002d/g, '-');
					
					document.getElementById('Q1Url').style.height = '90px';
					
					// url
					r = /"public_url":\{"canonicalUrlToShow":"[^"]+","canonicalUrl":"([^"]+)","showPublicProfileURL":true\}/.exec(rs);
					if (r) {
						document.getElementById('Q1Url').value = r[1];
						document.getElementById('Q1Url').style.border = '2px solid lime';
						if (/^https?:\/\/www\.linkedin\.com\//.exec(r[1])) {
							console.log('s');
							doSubmit();
						}
					} else {
					}
				}
			});
			
		}
