		function mturk_brent_vrma(url) {
			GM_xmlhttpRequest({ //
				method: "GET",
				url: url, //www.vrma.com/members/?id=10307641
				onload: function(response) {
					var rs = response.responseText;
					
					var r;
					var sbm = true;
					
					function mturk_brent_CharShiftDecrypt(strInVal, shiftval, shiftCharSet) {
						var strInString = new String(strInVal);
						var intInString = strInString.length;
						var strCharSet = new String(shiftCharSet);
						var intCharSetLen = strCharSet.length;
						var strOutVal = new String('');
						var nextchar, nextindex, ascii_nextchar, i;
						//for each character
						for (i = 0; i < intInString; i++) {
							// grab the next character to encrypt
							nextchar = strInString.substr(i, 1);
							//look it up in charset
							nextindex = strCharSet.indexOf(nextchar, 0)
							if (nextindex >= 0) { //found it
								nextindex = (nextindex - shiftval) % intCharSetLen // modulo this so can stay in bounds for next operation
								//check bounds of nextindex
								if (nextindex < 0) {
									nextindex = nextindex + intCharSetLen //wrap around to high end of charset
								}
								else if (nextindex >= intCharSetLen) { //this wont happen btw, becuase of modulo, but anyway
									nextindex = nextindex - intCharSetLen
								}
								strOutVal += strCharSet.charAt(nextindex);
							}
							else { //char not found in set, so add it as is
								strOutVal += nextchar;
							}
						}
						return strOutVal;
					}
					
					//em
					r = /var strEmail = CharShiftDecrypt\('([^']+)', (\d+), '([^']+)'\);/.exec(rs);
					if (r) {
						r = mturk_brent_CharShiftDecrypt(r[1], r[2]*1, r[3]);
						document.getElementById('email').value = r;
						if (!/^[^@]{1,}@[^$]{3,}$/.exec(r)) {
							sbm = false;
						}
					} else {
						r = /General Email Address:<\/label>&nbsp;&nbsp;<\/td><td class="CstmFldVal" colspan="2"><a href="\/search\/search\.asp\?cdlCustomFieldValueID\d+=[^"]+">([^<]+)<\/a>/.exec(rs);
					
						if (r) {
							r = r[1];
							r = __js_clean_html_str(r);
							r = r.trim();
							document.getElementById('email').value = r;
							if (!/^[^@]{1,}@[^$]{3,}$/.exec(r)) {
								sbm = false;
							}
						} else sbm = false;
					}
					
					//ph
					r = /<td valign="top" id="td[^"]+">[\r\n\t\s]+([\d+\-\s]{10,})[\r\n\t\s]+<span class="deemphasize">\((Mobile|Cell[^<]{0,})\)<\/span>/i.exec(rs);
					if (r) {
						document.getElementById('phone').value = __js_clean_html_str(r[1]).trim();
					} else {
						if (rs.indexOf('<span class="deemphasize">(Mobile)</span>') != -1)
							sbm = false;
						r = /<td valign="top" id="tdWorkPhone">[\r\n\t\s]+(\d{3}\s+\d{3}[\-\. ]\d{4}[\s\d+]{0,})(\s?ext\.?\s?\d+|)[\r\n\t\s]+<span class="deemphasize">\(Phone\)<\/span>/i.exec(rs);
						if (r) {
							document.getElementById('phone').value = __js_clean_html_str(r[1]).trim() +''+ __js_clean_html_str(r[2]).trim();
						} else sbm = false;
					}
					
					if (sbm) {
						doSubmit();
					}
				}
			});
		}
