		function brittany_graham_manta__process(input, rs) {  // INPUT NOT USED IN THIS FUNCTION !!
			
			// When using cached pages from Yahoo for Manta scrape
			// remove the bolding from Yahoo
			//<b style="color:#000;background:#ff66ff">
			rs = rs.replace(/<b style="[^"]*">((.|\s)*?(?=<\/b>|$)|$)/g, '$1');
			rs = rs.replace(/<\/b>/g, '');

			// SET THIS TO FALSE NOW THAT PAGE HAS LOADED
			PAGE_IS_LOADING = false;
			
			//input_btn.value = ' [load] ' + input_btn.value;
			txt_debug.value += '[load]';
			
			if  (
				rs.indexOf('It looks like you\'ve been very active on Manta&mdash;and that\'s great! Do us a favor and confirm you are human by filling out the bold type below.') != -1 ||
				rs.indexOf('It looks like the characters you entered did not match the image. Please help us out by reentering the characters in bold type below.') != -1 ||
				(
					rs.indexOf('Company Profile') == -1 &&
					rs.indexOf('company_name') == -1 &&
					rs.indexOf(' – Manta.com</title>') == -1 &&
					rs.indexOf('<html lang="en" ng-app="app" id="ng-app">') == -1 // new ??
				)
				)
			{
				d1.style.backgroundColor = 'yellow';
				return;
			}
			
			var r;
			var sbm = true;
			
			r = /<span itemprop="name">([^<]+)<\/span>/.exec(rs);
			if (!r)
				r = /<p itemprop="name">([^<]+)<\/p>/.exec(rs); // p vs span
			if (!r)
				r = /<h6 class="" itemprop="name">([^<]+)<\/h6>/.exec(rs); //
			if (!r)
				r = /<img src="\/manta\/images\/company_profile\/icon_contact[^"]+"[\r\n\t\s]+alt="([^"]+)"/.exec(rs); //
			if (!r)
				r = /contacts"\s+rel="nofollow"\s+class="h5">([^<]+)<\/a>/.exec(rs); //
			if (!r)
				r = /<span class="text-primary" itemprop="name">([^<]+)<\/span>/.exec(rs); //
			//if (!r)
			//	r = /<h6 class="left"><a rel="nofollow" href="[^"]+"><span itemprop="name">Ming Chiang</span></a>([^<]+)<\/a>/.exec(rs); //
			if (r) {
				r = r[1];
				
				r = __js_clean_html_str(r);
				r = r.trim();
				r = r.replace(/ (jr|sr|junior|senior|ii|iii|iv|v|phd|md|dds)\.?$/i, '');
				r = r.replace(/,\s*(owner|manager|partner|president)$/i, '');
				r = r.replace(/^(mr|mrs|miss|ms|sir|dr|doctor|md|phd)\.? /i, '');
				r = r.replace(/\s+/, ' ');
				r = r.trim();
				
				if (/^\w+\s+\w\.?\s+\w+$/.exec(r)) { // remove middle initial
					r = r.replace(/^(\w+)\s+\w\.?\s+(\w+)$/, '$1 $2');
				}
				
				if (r.indexOf(',') != -1) {
					txt_debug.value += '[comma]';
				}
				
				r = r.split(' ');
				if (r.length == 2) {
					document.getElementById('First Name').value = r[0];
					document.getElementById('Last Name').value = r[1];
					if (sbm)
						doSubmit();
				} else {
					document.getElementById('First Name').value = r[0];
					document.getElementById('Last Name').value = r.slice(1).join(' ');
					sbm = false;
					txt_debug.value += '[space]';
					
				}
			} else {
				if (rs.indexOf('itemprop="jobTitle"') == -1) {
					txt_debug.value += '[none]';
				} else {
					//
					console.log('job title');
				}
				sbm = false;
			}
			
			if (txt_debug.value != '[load]' && txt_debug.value.trim() != '') {
				//console.log('txt_debug:'+txt_debug.value);
				txt_debug.style.border = '6px solid orange';
			}
		}
