		function christian_j_hirning_bw_done(u) {
			
			var x;
			x = u.replace(/(\?personId=\d+)&[\d\D]+$/, '$1'); // shorter
			
			d2.value = 'Loading ' + "\n" + u; 
			
			if (x != u)
				var xyint = setTimeout(function() { christian_j_hirning_bw_done(x) }, 10000);
				
			
			GM_xmlhttpRequest({
				method: "GET",
				url: u,
				onload: function(response) {
					var rs=response.responseText;
					
					if (response.status != 200) {
						d1.innerHTML = response.status;
						return;
					}
					
					var r;
					r = /<h2 class="sectionTitle">Background\*?<\/h2>[\r\n\t\s]+([^\r\n]+)/.exec(rs);
					if (r) {
						r = r[1];
						r = r.trim();
						r = r.replace(/^<p>/, '');
						r = r.replace(/<span id="dots"> \.\.\.<\/span><span id="hidden" style="display:none">/, '');
						r = r.replace(/<\/span><div style="margin-top:8px;"><a href="javascript:void\(0\)" onclick="show_more\(this\);">Read Full Background<\/a><\/div>(<\/p>|)$/, '');
						r = r.replace(/<\/p>$/, '');
						r = r.trim();
						
						d2.value = r;
						
						if (xyint)
							clearTimeout(xyint);
						
						if (r.indexOf('<') != -1 || r.length < 10)
							document.body.style.backgroundColor = 'teal';
						else {
							document.getElementById('Q1Url').value = r;
							doSubmit();
						}
					}
					
				}
			});
		}
