	function kristin_howe_realty() {
		// Yahoo
		var u = 'http://search.yahoo.com/search?p=%2B'+encodeURIComponent(b); //%2B
		d1.innerHTML = '';
		GM_xmlhttpRequest({
			method: 'GET',
			url: u,
			onload: function (response) {
				var rs=response.responseText;
				var rg = /yschttl spt" href="[^*]+[*]+([^"]+)"[^>]+>((.|\s)*?(?=<\/li>|$)|$)/g;
				
				if (rg.exec(rs) && rs.indexOf('Including results for') == -1) {
					rg.lastIndex = 0;
					rg=/yschttl spt" href="[^*]+[*]+([^"]+)"[^>]+>((.|\s)*?(?=<\/li>|$)|$)/g; // li
					var count=0;
					var r2, x, match, out;
					while (match = rg.exec(rs)) {
						if (count >= 8)
							break;
						count++;
						
						match[1] = decodeURIComponent(match[1]);
						
						match[2] = match[2].replace(/<b>/g, '');
						match[2] = match[2].replace(/<\/b>/g, '');
						match[2] = match[2].replace(/^[^>]+>/, ' '); // first close
						match[2] = match[2].replace(/<[^>]+>/g, ' ');
						match[2] = match[2].replace(/[<>]/g, ' ');
						//match[2] = match[2].replace(/'/g, "\'");
						//match[2] = match[2].replace(/``/g, '</b>');
						//match[2] = match[2].replace(/`/g, '<b>');
						
						x = match[1];
						x = x.replace(/(\w+)\/[\d\D]{0,}$/, '$1'); //trailing
						//x = x.replace(/^https?:\/\/(www\.|)/, ''); //beginning
						
						if (__js_inarray(skips, x)) {
							d1.innerHTML += '<p>-</p>';
							continue;
						}
						
						match[1] = match[1].replace(/^(https?:\/\/[^\/]+)\/$/, '$1'); //if trailing
						
						if (x != match[1]) {
							x = '<input type="button" value="'+x+'" class="exe" ><input type="button" value=" -s- " id="'+count+'|||'+x+'" class="exe2" ><br >';
							//xx check both
						} else {
							x = '';
							//xx check one
						}
						
						//var y, o = '';
						//r2 = /([a-z0-9]+([_\.-][a-z0-9]+)*(@|[ ]{0,}\[at\][ ]{0,}|&#064;)([a-z0-9]+([\.-][a-z0-9]+)*)+\.[a-z]{2,})/gi;
						//if (r2.exec(match[2])) {
						//	r2.lastIndex = 0;
						//	while (y = r2.exec(match[2])) {
						//		o += '<br ><input type="button" value="'+y[0]+'" class="ex__whois" ><br >';
						//	}
						//}
						//match[2] += o;
						
						d1.innerHTML += '<p><input type="button" value="'+match[1]+'" class="exe" ><input type="button" value=" -s- " id="'+count+'|||'+match[1]+'" class="exe2" ><br >'+x+match[2]+'</p>';
						
						//d3.innerHTML += '<p>'+x+'<br >'+match[1]+'<br >'+match[2]+'</p>';
						//d3.innerHTML += '<p><input type="button" value="'+x+'" class="ex__yahoo" ><br >'+match[1]+'<br >'+match[2]+'</p>';
						
					}
					
					var x = document.getElementsByClassName('exe');
					for (var i in x) {
						x[i].onclick = function() {
							document.getElementById('homepage').value = this.value;
							doSubmit();
						}
					}
					var x = document.getElementsByClassName('exe2');
					for (var i in x) {
						x[i].onclick = function() {
							kristin_howe_addSkip(this.id);
						}
					}
				} else
					d1.innerHTML = '0';
			}
		});
	}
