	function kristin_howe_addSkip(u) {
		var u = u.split('|||');
		console.log(u);
		GM_xmlhttpRequest({
			method: 'GET',
			url: 'http://localhost/mturk/KristinHowe/KristinHowe.php?u='+encodeURIComponent(u[1])+'&id='+encodeURIComponent(u[0]),
			onload: function (response) {
				var rs = response.responseText;
				var r;
				r = response.finalUrl;
				r = /u=([^&]+)&id=([\d\D]+)/.exec(r);
				if (r) {
					r[1] = decodeURIComponent(r[1]);
					r[2] = decodeURIComponent(r[2]);
					document.getElementById(r[2]+'|||'+r[1]).style.backgroundColor = 'lime';
				}
			}
		});
	}
	
