	function mark_fiske_google(qry, ite) {
		GM_xmlhttpRequest({
			method: "GET",
			//url: 'http://www.google.de/search?hl=de&biw=1440&bih=812&output=search&sclient=psy-ab&q='+encodeURIComponent(qry),
			//url: 'http://www.google.de/search?hl=de&num=1&q='+encodeURIComponent(qry),
			url: qry,
			onload: function(response) {
				var rs=response.responseText;
				var rg;
				
				rg=/<h3 class="r"><a href="([^"]+)/;
				if (rg.exec(rs)) {
					ite.value = rg.exec(rs)[1];
				} else if (/ - did not match any documents./.exec(rs)) {
					ite.value = 'NONE';
				}
			}
		});
	}
	
