	// Skylar Marcum
	// LinkedIn followers/employees
	//
	s='*PREREQUISITES* - to complete these hits, you must first be LOGGED IN TO LINKED IN. &nbsp;To sign up for an account is free, simply requires email validation. &nbsp;You will only have to log in once, at which point&nbsp;you will be able to complete tasks at a fast pace.';
	if (ih.indexOf(s) != -1) {
		console.log('');
		
		var a,id;
		//~ a = /<td>LinkedIn Profile:<\/td>[\r\n\t\s]*<td>(http:\/\/www\.linkedin\.com\/company\/[^<]*)<\/td>/.exec(ih)[1];
		var td = document.getElementsByTagName('td');
		var o = {
			url: td[3].innerText.trim()
		}
		a = o.url;
		//~ console.log(a);
		
		var rf = new AMT___requests_factory();
		id = rf.general_functions__md5(a);
		
		var qa = [
			document.getElementsByName('followers')[0],
			document.getElementsByName('employees')[0]
		];
		
		rf.io__read_file(
			{
				filename: MT___host + '/mturk/.cached/' + encodeURIComponent(id)
			},
			function(response) {
				if (response.status == 200) {
					var rs;
					rs = response.responseText;
					Skylar_Marcum_linkedin__process(rs)
				} else {
					GM_xmlhttpRequest({
						method: "GET",
						url: a,
						onload: function(response) {
							var rs=response.responseText;
							
							rf.io__write_to_file(
								{
									data:	'AMT__serverSide_write__value='		+ encodeURIComponent(rs)+
											'&AMT__serverSide_write__folder=.cached'+
											'&AMT__serverSide_write__file='		+ encodeURIComponent(id),
									rs:		rs // for callback !!
								},
								Skylar_Marcum_linkedin__process
							);
						}
					});
				}
			}
		);
	}
	function Skylar_Marcum_linkedin__process(rs) {
		
		if (rs.rs)
			rs = rs.rs;
		else
			rs = rs.responseText;
		
		var r;
		r=/extra_biz_employees_deg_connected">([^<]+)/;
		if (r.exec(rs)) {
			r = r.exec(rs)[1].trim();
			//r = r.replace(/[\D]/g, '');
			
			qa[1].value = r;
		}
		else if (/Overview \| LinkedIn<\/title>/.exec(rs))
		{
			qa[1].value = '0';
		}
		else // err !?
		{
			
		}
		
		r=/trk=extra_biz_followers"><strong>([\d,]+)<\/strong> <span class="[^"]*">followers?<\/span><\/a>/;
		if (r.exec(rs)) {
			r = r.exec(rs)[1].trim();
			//r = r.replace(/[\D]/g, '');
			
			qa[0].value = r;
		}
		else if (/Overview \| LinkedIn<\/title>/.exec(rs))
		{
			//qa[0].value = '0';
			console.log('followers');
		}
		else // err !?
		{
			
		}
		
		if  (
			qa[0].value != '' &&
			qa[1].value != ''
			)
		{
			doSubmit();
		}
	}
	
