					var theValue = this.value;
					var id = "Answer_"+this.parentNode.parentNode.id+"_FreeText";
					var x = document.getElementById(id); // answer text area
					x.focus();
					var y = x.happyJoyJoy;
					
					console.log(this.parentNode.parentNode.id*1)
					
					if(__js_inarray(phoneFaxIdArray, this.parentNode.parentNode.id*1)) // phone/fax
					{
						theValue = (theValue.indexOf('FEDBID') == -1) ? theValue.replace(/[\D]/g,"") : theValue;
						if (y) { // is modified
							if (x.value == 'n/a')
								x.value = '';
							x.value += theValue
						} else {
							x.happyJoyJoy = 1;
							x.value = theValue
						}
					}
					else if (__js_inarray(middleInitialIdArray, this.parentNode.parentNode.id*1)) // middle init
					{
						theValue = theValue.toUpperCase()[0] + '.';
						if (y) { // is modified
							if (x.value == 'n/a')
								x.value = '';
							x.value += theValue
						} else {
							x.happyJoyJoy = 1;
							x.value = theValue
						}
					}
					else // everything else
					{											
						if (y) { // is modified
							if (x.value == 'n/a')
								x.value = '';
							x.value += ' '+this.value.replace(/[,;]+$/, '');
							x.value = x.value.trim();
						} else {
							x.happyJoyJoy = 1;
							x.value = this.value.replace(/[,;]+$/, '');
						}
					}
					
