		// copy to next function
		function Fiber_Data_Co_Validate_Contacts__CopyNext(el, oneCopyThree) {
			var id = el.parentNode.id*1;
			
			var next_id = (oneCopyThree) ? id + 2 : id + 1;
			
			var tmp_arr = [];
			var next_overview = document.getElementsByClassName("overview-wrapper")[next_id];
			for (var i = ((id-1) * 7)+1; i<=((id-1)*7) + 7; i++) {
				var next = (oneCopyThree) ? Math.round(i*1 + 14) : Math.round(i*1 + 7);console.log(next);
				var val = document.getElementById("Answer_"+i+"_FreeText").value;
				document.getElementById("Answer_"+next+"_FreeText").value = val;
				tmp_arr.push(val);
			}
			el.style.backgroundColor = 'lightgreen';
			
			// highlight for the diff! (o, arr, type)
			var tmp_notes = next_overview.innerText;
			var hl = Fiber_Data_Co_MT__highLight(
				tmp_notes,
				tmp_arr
			);
			next_overview.innerHTML += hl.highlightString + '<br>';
			// re-apply
			if (next_overview.getElementsByTagName('input')[1]) {// is 1 or 2 (not 3)
				next_overview.getElementsByTagName('input')[1].onclick = function() {
					Fiber_Data_Co_Validate_Contacts__CopyNext(this);
				}
			}
		}
