		function Fiber_Data_Co_update(text, num_form) {
			
			var ntext;console.log(text);
			var word_index;
			var count_com, count_semi;
			
			//text = n;
			text_original = text;
			text = text.replace(/\s+US$/i, '');
			//text = '"'+text;//debug &quot;
			
			count_com = (text.match(/,/g)) ? text.match(/,/g).length : 0; // true or null
			count_semi = (text.match(/;/g)) ? text.match(/;/g).length : 0;
			
			// semi colon 
			text_original = text_original.replace(/\s+,/g, ',');
			text_original = text_original.replace(/,\s*/g, ', ');
			text_original = text_original.replace(/,\s*,/g, '');
			text_original = text_original.replace(/\s+;/g, ';');
			text_original = text_original.replace(/\s+/g, ' ');
			//text_original = text_original.replace(/"/g, '&quot;');
			text_original = text_original.split(';'); // split semi!
			
			text = text.replace(/;/g, ' '); // !no semi!
			text = text.replace(/\s+,/g, ',');
			text = text.replace(/,\s*/g, ', '); // keep ",," else ", word"
			text = text.replace(/,\s*,/g, ''); // keep ",," else ", word"
			//text = text.replace(/,+/g, ',');
			text = text.replace(/\s+;/g, ';');
			text = text.replace(/\s+/g, ' ');
			text = text.replace(/"/g, '&quot;');
			text = text.trim();
			
			ntext = text;
			text = text.split(' ');
			
			//change ntext
			//ntext = ntext.replace(/,( [a-z]{2} \d+)$/, '$1');
			
			var d = document.getElementById('update_'+num_form);
			word_index = 0; //
			for (var j in text) {
				d.innerHTML += '\
				<input type="button" value="'+text[j]+'" id="'+num_form+'|'+word_index+'" class="exe exe'+num_form+'">';
				//p[i].innerHTML += '\
				//<input type="button" value="'+text[j]+'" id="'+num_form+'|'+word_index+'" class="exe exe'+num_form+'">';
				word_index++;
			}
			// add "finalize"
			d.innerHTML += '\
				<input type="button" value="[ &nbsp;final&nbsp;  ]" id="'+num_form+'" class="exe-final">';
			
			//num_form++;
			
			// auto fill?
			// AUTO FILL
			// watch <br>
			// p[i] => i = 0,1,...5
			
			//console.log(count_com);
			//console.log(count_semi);
			// duns? no auto ///////
			if (/duns/i.exec(text)) return;
			//if (/duns/i.exec(text)) continue; // skip
			
			// count_auto is global?
			if (count_semi > count_com && count_semi == 4) { //nm,str,city,st,zip
				var c = 0;
				for (var j = form_counter_array[i]; j < form_counter_array[i]+5; j++) {
					var fid = document.getElementById('Answer_'+j+'_FreeText');
					fid.value = text_original[c];//.replace(/&quot;/g, '"');
					//fid.value = text_original[c].replace(/&quot;/g, '"');
					c++;
				}
				count_auto++;
			} else if (count_com == 3) {
				var n = /^([^,]+),([^,]+),([^,]+), ([a-z]{2})\s+([\d\-]+)$/i.exec(ntext);
				if (n) {
					var c = 1;
					for (var j = form_counter_array[i]; j < form_counter_array[i]+5; j++) {
						var fid = document.getElementById('Answer_'+j+'_FreeText');
						fid.value = n[c].trim().replace(/&quot;/g, '"');
						c++;
					}
					count_auto++;
				}
			} else {
				// 4 commas w/inc, llc, etc?
				var n = /^([^,]+,[^,]+),([^,]+),([^,]+), ([a-z]{2})\s+([\d\-]+)$/i.exec(ntext);
				if (n) {
					if (/^[^,]+, (llc|llp|plc|inc|incorporated|the)\.?$/i.exec(n[1])) {
						var c = 1;
						for (var j = form_counter_array[i]; j < form_counter_array[i]+5; j++) {
							var fid = document.getElementById('Answer_'+j+'_FreeText');
							fid.value = n[c].trim().replace(/&quot;/g, '"');
							c++;
						}
						count_auto++;
					}
				}
			}
		}
